/* Gemaakt door docs/handleiding/build.py --app. Niet met de hand aanpassen. */
window.KMA_HANDLEIDING = {"app": "boek", "css": "@page { size: A4; }\n:root { --green:#18251D; --deep:#0C140F; --gold:#D8CB92; --gold-d:#8A7A3A; --red:#B5272D; --ink:#1E2621; --muted:#5F6A63; --paper:#FBFAF5; --line:#E3DFCF; }\n* { box-sizing: border-box; }\nhtml, body { margin: 0; }\nbody { font: 400 10pt/1.5 'KMA Tekst', sans-serif; color: var(--ink); -webkit-print-color-adjust: exact; print-color-adjust: exact; }\nh1, h2, h3, h4 { font-family: 'KMA Tekst', sans-serif; color: var(--green); margin: 0; }\nb { font-weight: 700; }\n.tok { color: #fff; font-size: 1pt; position: absolute; }\n.sec { break-before: page; position: relative; }\n.kicker { font: 700 8pt 'KMA Tekst'; letter-spacing: .16em; text-transform: uppercase; color: var(--gold-d); margin-bottom: 4pt; padding-top: 2pt; border-top: 2.2pt solid var(--gold); display: inline-block; }\nh2 { font-size: 22pt; line-height: 1.15; margin: 2pt 0 6pt; letter-spacing: -.01em; }\n.lead { font-size: 11pt; color: #3b4640; margin: 0 0 12pt; max-width: 165mm; }\nh3 { font-size: 13pt; margin: 0 0 6pt; }\nh4 { font-size: 11pt; margin: 0 0 4pt; }\n.tut { break-inside: avoid; padding: 10pt 0 12pt; border-top: .6pt solid var(--line); }\n.tut.row { display: grid; grid-template-columns: 1fr 58mm; gap: 9mm; align-items: start; }\n.steps { list-style: none; counter-reset: s; margin: 0 0 6pt; padding: 0; }\n.steps li { counter-increment: s; position: relative; padding: 0 0 5pt 24pt; }\n.steps li::before { content: counter(s); position: absolute; left: 0; top: 0; width: 15pt; height: 15pt; border-radius: 50%; background: var(--green); color: var(--gold); font: 700 8pt/15pt 'KMA Tekst'; text-align: center; }\n.phones { display: flex; gap: 10mm; justify-content: center; flex-wrap: wrap; margin-top: 4pt; }\n.tut.row .phones { margin-top: 0; }\n.phone { margin: 0; width: 56mm; text-align: center; }\n.phone img { width: 100%; display: block; border: 1.8mm solid #161a17; border-radius: 5mm; box-shadow: 0 2mm 5mm rgba(0,0,0,.18); background: #161a17; }\n.phone figcaption { font-size: 8pt; color: var(--muted); margin-top: 4pt; }\n.call { border-left: 3pt solid; padding: 5pt 8pt; margin: 5pt 0; border-radius: 0 4pt 4pt 0; font-size: 9.2pt; break-inside: avoid; }\n.call b { display: inline-block; margin-right: 4pt; text-transform: uppercase; font-size: 7.6pt; letter-spacing: .08em; }\n.call.tip { background: #EAF3EC; border-color: #3FA66B; } .call.tip b { color: #2E7D50; }\n.call.let { background: #FBECEC; border-color: var(--red); } .call.let b { color: var(--red); }\n.call.privacy { background: #F3EFE0; border-color: var(--gold-d); } .call.privacy b { color: var(--gold-d); }\n.call.info { background: #EAF0F7; border-color: #5B9BD5; } .call.info b { color: #3D78B0; }\n.legend { display: flex; gap: 8pt; margin-top: 8pt; } .legend .call { margin: 0; flex: 1; }\n.twocol { display: grid; grid-template-columns: 1fr 1fr; gap: 8mm; margin: 6pt 0 14pt; }\n.card { border: .8pt solid var(--line); background: var(--paper); border-radius: 6pt; padding: 10pt 12pt; }\n.card.dark { background: var(--green); border-color: var(--green); color: #E9E7DD; } .card.dark h4 { color: var(--gold); }\n.card p { margin: 0; }\nul.plain { margin: 0 0 10pt; padding-left: 14pt; } ul.plain li { margin-bottom: 5pt; }\n.faq .q { break-inside: avoid; border-top: .6pt solid var(--line); padding: 8pt 0; } .faq p { margin: 0; }\ndl.terms { display: grid; grid-template-columns: 38mm 1fr; gap: 6pt 10pt; margin: 0; }\ndl.terms dt { font-weight: 700; color: var(--green); } dl.terms dd { margin: 0; }\n/* TOC */\n.toc h2 { margin-bottom: 10pt; }\n.toc-part { font: 700 8pt 'KMA Tekst'; letter-spacing: .14em; text-transform: uppercase; color: var(--gold-d); margin: 10pt 0 3pt; }\n.toc-row { display: flex; align-items: baseline; gap: 6pt; padding: 2.2pt 0; font-size: 10pt; }\n.toc-row .n { display: none; }\n.toc-row .dots { flex: 1; border-bottom: .8pt dotted #b9b3a0; transform: translateY(-3pt); }\n.toc-row .p { width: 18pt; text-align: right; font-weight: 700; }\n/* cover */\n.cover { width: 210mm; height: 297mm; background: radial-gradient(ellipse 80% 55% at 50% 30%, #1d2e23 0%, #132019 50%, #0C140F 85%); color: #F1F0E9; position: relative; overflow: hidden; }\n.cv-top { text-align: center; padding-top: 26mm; }\n.cv-emb { width: 34mm; filter: drop-shadow(0 0 8mm rgba(216,203,146,.35)); }\n.cv-k { font: 600 9pt 'KMA Tekst'; letter-spacing: .32em; text-transform: uppercase; color: var(--gold); margin: 9mm 0 4mm; }\n.cover h1 { color: #F1F0E9; font-size: 38pt; letter-spacing: -.01em; }\n.cv-sub { font: 500 14pt 'KMA Tekst'; color: #AEB5AF; margin-top: 3mm; }\n.cv-phones { position: absolute; left: 0; right: 0; top: 128mm; display: flex; justify-content: center; align-items: flex-start; gap: 7mm; }\n.cv-phones img { width: 50mm; border: 1.6mm solid #050806; border-radius: 5mm; box-shadow: 0 4mm 10mm rgba(0,0,0,.5); }\n.cv-phones img:nth-child(2) { width: 56mm; margin-top: -8mm; }\n.cv-foot { position: absolute; bottom: 14mm; left: 0; right: 0; text-align: center; font-size: 9pt; color: #AEB5AF; letter-spacing: .04em; }\n.phones:has(> .phone:nth-child(3)) { gap: 6mm; flex-wrap: nowrap; } .phones:has(> .phone:nth-child(3)) .phone { width: 48mm; }\ntable.roles { width: 100%; border-collapse: collapse; font-size: 9pt; margin: 6px 0 4px; }\ntable.roles th, table.roles td { border-bottom: 1px solid #dfe3dc; padding: 5px 6px; text-align: center; }\ntable.roles td:first-child, table.roles th:first-child { text-align: left; }\ntable.roles thead th { background: #1f2b22; color: #fff; font-weight: 600; }\ntable.roles tbody tr:nth-child(even) td { background: #f5f6f2; }\n\n/* Klikbare inhoudsopgave en verwijzingen (4.5.1) */\na.toc-row, a.ref { color: inherit; text-decoration: none; }\n", "html": "<div class=\"ho-top\"><h1>Handleiding &amp; tutorials</h1><p class=\"lead\">Het deel over het Reflectieboekje. Tik op een onderwerp, of bij een hoofdstuk op <b>Open dit hoofdstuk in de app</b>. Woorden met een pijltje (↗), zoals <i>⋮ → Herinneringen</i> of <i>hoofdstuk 5</i>, brengen je meteen naar die plek in de app.</p><section class=\"toc ho-toc\"><h2>Inhoud</h2><div class=\"toc-part\">Deel A · Reflectieboekje</div><a class=\"toc-row\" href=\"#A1\"><span class=\"n\">A1</span><span class=\"t\">De eerste keer starten</span></a><a class=\"toc-row\" href=\"#A1b\"><span class=\"n\">A1b</span><span class=\"t\">Samenhang: volgende stap en begrippen</span></a><a class=\"toc-row\" href=\"#A2\"><span class=\"n\">A2</span><span class=\"t\">Hoofdstuk 0 · Cadet Informatie &amp; Profiel</span></a><a class=\"toc-row\" href=\"#A3\"><span class=\"n\">A3</span><span class=\"t\">Hoofdstuk 1 · Introductie &amp; Drijfveren</span></a><a class=\"toc-row\" href=\"#A4\"><span class=\"n\">A4</span><span class=\"t\">Hoofdstuk 2 · Ontwikkelbiografie Tijdlijn</span></a><a class=\"toc-row\" href=\"#A5\"><span class=\"n\">A5</span><span class=\"t\">Hoofdstuk 3 · Persoonlijkheidstest</span></a><a class=\"toc-row\" href=\"#A6\"><span class=\"n\">A6</span><span class=\"t\">Hoofdstuk 4 · Ik en de Gedragscode Defensie</span></a><a class=\"toc-row\" href=\"#A7\"><span class=\"n\">A7</span><span class=\"t\">Hoofdstuk 5 · SMART Leervraag</span></a><a class=\"toc-row\" href=\"#A8\"><span class=\"n\">A8</span><span class=\"t\">Hoofdstuk 6 · Zelfreflectie Leervraag (5G-T)</span></a><a class=\"toc-row\" href=\"#A9\"><span class=\"n\">A9</span><span class=\"t\">Hoofdstuk 7 · Procesreflectie (Korthagen)</span></a><a class=\"toc-row\" href=\"#A10\"><span class=\"n\">A10</span><span class=\"t\">Hoofdstuk 8 · Datum-Tijd-Feit Logboek</span></a><div class=\"toc-part\">Deel A · Reflectieboekje · Verdieping</div><a class=\"toc-row\" href=\"#A11\"><span class=\"n\">A11</span><span class=\"t\">Hoofdstuk 9 · Zelfbeoordelingsformulier KMA</span></a><a class=\"toc-row\" href=\"#A12\"><span class=\"n\">A12</span><span class=\"t\">Hoofdstuk 10 · Voorbereiding Cadetbeoordeling</span></a><a class=\"toc-row\" href=\"#A13\"><span class=\"n\">A13</span><span class=\"t\">Hoofdstuk 11 · Probleem- en Behoefteanalyse</span></a><a class=\"toc-row\" href=\"#A14\"><span class=\"n\">A14</span><span class=\"t\">Hoofdstuk 12 · Fitheid &amp; stress</span></a><a class=\"toc-row\" href=\"#A15\"><span class=\"n\">A15</span><span class=\"t\">Hoofdstuk 13 · Curriculum vitae</span></a><div class=\"toc-part\">Deel A · Reflectieboekje · Naslag en overzicht</div><a class=\"toc-row\" href=\"#A16\"><span class=\"n\">A16</span><span class=\"t\">Hoofdstuk 14 · Toetsing en examinering DKOO</span></a><a class=\"toc-row\" href=\"#A17\"><span class=\"n\">A17</span><span class=\"t\">Hoofdstuk 15 · Begrippenlijst &amp; Vakjargon</span></a><a class=\"toc-row\" href=\"#A18\"><span class=\"n\">A18</span><span class=\"t\">Hoofdstuk 16 · Mijn groei &amp; ontwikkeling</span></a><a class=\"toc-row\" href=\"#A19\"><span class=\"n\">A19</span><span class=\"t\">Hoofdstuk 17 · Roos van Leary</span></a><div class=\"toc-part\">Deel A · Reflectieboekje</div><a class=\"toc-row\" href=\"#A20\"><span class=\"n\">A20</span><span class=\"t\">Je portfolio als PDF</span></a><a class=\"toc-row\" href=\"#A21\"><span class=\"n\">A21</span><span class=\"t\">Je dossier delen met je teamleider</span></a><a class=\"toc-row\" href=\"#A22\"><span class=\"n\">A22</span><span class=\"t\">Versleuteld delen en de deelmap</span></a><a class=\"toc-row\" href=\"#A23\"><span class=\"n\">A23</span><span class=\"t\">Back-up maken en terugzetten</span></a><a class=\"toc-row\" href=\"#A24\"><span class=\"n\">A24</span><span class=\"t\">Feedback van je teamleider ontvangen</span></a><a class=\"toc-row\" href=\"#A25\"><span class=\"n\">A25</span><span class=\"t\">Feedback van en voor medecadetten</span></a><a class=\"toc-row\" href=\"#A26\"><span class=\"n\">A26</span><span class=\"t\">De Dashboard-weergave in het Reflectieboekje</span></a><div class=\"toc-part\">Deel A · Reflectieboekje · Naslag en overzicht</div><a class=\"toc-row\" href=\"#A19\"><span class=\"n\">A19</span><span class=\"t\">Hoofdstuk 17 · Roos van Leary</span></a></section></div><section class=\"sec\" id=\"A1\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>De eerste keer starten</h2><p class=\"lead\">Na het openen speelt een kort introfilmpje (tik erop om het over te slaan). Daarna kom je op de startpagina van je Reflectieboekje.</p><div class=\"tut\"><h3>Akkoord met de gebruiksvoorwaarden</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Bij de eerste start toont de app de <b>gebruiksvoorwaarden</b> (EULA): eerst een korte samenvatting, daaronder de volledige tekst.</li><li>Lees de voorwaarden. Zet daarna een vinkje bij <b>Ik heb de gebruiksvoorwaarden gelezen en ga akkoord</b> en tik op <b>Akkoord en verder</b>.</li><li>Tik je op <b>Niet akkoord</b>, dan kun je de app niet gebruiken.</li><li>De app onthoudt je akkoord. Worden de voorwaarden later gewijzigd, dan vraagt de app opnieuw om je akkoord.</li><li>Wil je de voorwaarden teruglezen? Tik onderaan het scherm op <b>© 2026 T.T.W. Gramser</b>. Je ziet dan ook wanneer je akkoord ging.</li></ol><div class=\"call info\"><b>Goed om te weten</b> Kort gezegd: de app is van de maker en je gebruikt hem voor je opleiding aan de KMA. Wat jij invult, blijft van jou en staat alleen op je eigen toestel (zie pagina C0).</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Eerste start</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Teruglezen</figcaption></figure></div></div><div class=\"tut\"><h3>Een demodossier bekijken</h3><ol class=\"steps\"><li>Wil je eerst zien hoe een volledig ingevuld boekje eruitziet? Open dan in een <b>leeg</b> Reflectieboekje <a class=\"ho-go\" data-menu=\"Demodossier\"><b>⋮ → Demodossier</b></a>.</li><li>Kies een van de drie fictieve cadetten: <b>Daan Verhoeven</b> (CLAS, leervraag delegeren), <b>Noor El Amrani</b> (CLSK, leervraag luisteren) of <b>Ruben de Graaf</b> (CZSK, leervraag besluitvaardigheid, met een hoge stressscore).</li><li>Het boekje van die cadet staat dan in de app, met alle hoofdstukken, reflecties, DTF-feiten, check-ins en de feedback van de teamleider. Kijk overal rond en probeer alles uit.</li><li>Klaar? Wis het boekje met <a class=\"ho-go\" data-menu=\"Alles wissen\"><b>⋮ → Alles wissen</b></a> en begin aan je eigen boekje.</li></ol><div class=\"call let\"><b>Let op</b> Een demodossier kan alleen in een leeg boekje, zodat je nooit per ongeluk je eigen antwoorden overschrijft. Deel een demodossier niet met je teamleider: het is fictief.</div></div><div class=\"tut row\"><div class=\"txt\"><h3>De startpagina</h3><ol class=\"steps\"><li>Bovenaan zie je de knop <a class=\"ho-go\" data-click=\"#kma-share-btn\"><b>Delen</b></a> en de knop <b>⋮</b> (meer opties). Alles wat je deelt, loopt via <a class=\"ho-go\" data-click=\"#kma-share-btn\"><b>Delen</b></a>.</li><li>Onder de introductietekst staat de kaart <b>Voortgang</b>: hoeveel vragen en onderdelen je al hebt ingevuld.</li><li>Daaronder staat de kaart <b>Vandaag</b>: wat er nu te doen is, en <b>Ga verder</b> om terug te gaan naar waar je gebleven was (zie hieronder).</li><li>Scrol omlaag om met het eerste hoofdstuk te beginnen, of kies een hoofdstuk onder <b>Vaste basis</b>, <b>Verdieping</b> of <b>Naslag en overzicht</b>.</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Startpagina</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>De kaart Vandaag</h3><ol class=\"steps\"><li>Op de startpagina staat de kaart <b>Vandaag</b>. Hij laat alleen zien wat nu belangrijk is, met per punt een knop.</li><li><b>SMART-check-in</b>: heb je deze week nog niet ingecheckt, dan staat dat er. <b>Nieuwe feedback</b>: je teamleider stuurde iets dat je nog niet las.</li><li><b>Gesprek</b> of <b>evaluatie</b>: staat er binnenkort een gesprek of je SMART-evaluatiedatum, dan zie je hoeveel dagen het nog duurt, met de knop <b>Voorbereiden</b>.</li><li><b>Afspraak</b>: een afspraak uit een gespreksverslag van je teamleider. Tik op <b>Gedaan</b> als je hem hebt uitgevoerd; je teamleider ziet dat bij de volgende keer delen.</li><li><b>Back-up</b>: maakte je al lang (of nog nooit) een back-up, dan herinnert de kaart je eraan.</li><li>Onderaan staat <b>Ga verder</b> met het hoofdstuk waar je gebleven was. Is er niets te doen, dan zie je alleen dat.</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>De kaart Vandaag</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Herinneringen</h3><ol class=\"steps\"><li>Open <a class=\"ho-go\" data-menu=\"Herinneringen\"><b>⋮ → Herinneringen</b></a> en zet aan wat je wilt: de <b>wekelijkse check-in</b> (kies de dag en de tijd), je <b>evaluatiedatum</b> (drie dagen ervoor en op de dag zelf), <b>nieuwe feedback</b> en een <b>back-up</b> als je die lang niet maakte.</li><li>De eerste keer vraagt je toestel of de app meldingen mag sturen. Kies <b>Toestaan</b>.</li><li>Op Android en iPhone komen de herinneringen ook als de app dicht is. In de web-app alleen zolang de pagina open staat.</li></ol><div class=\"call privacy\"><b>Privacy</b> Een herinnering bevat geen antwoorden of feedback, alleen een korte zin zoals <i>Tijd voor je SMART-check-in</i>.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>⋮ → Herinneringen</figcaption></figure></div></div><div class=\"tut\"><h3>Bereid je gesprek voor</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Open <a class=\"ho-go\" data-menu=\"Bereid je gesprek voor\"><b>⋮ → Bereid je gesprek voor</b></a>, of tik op <b>Voorbereiden</b> in de kaart Vandaag.</li><li>Vul de datum van het gesprek in en kies wat je meeneemt: je <b>SMART-leervraag</b> en check-ins, je laatste <b>reflecties</b>, de <b>feedback</b> die je kreeg en, als je dat wilt, je <b>stresscheck</b> (alleen op je eigen papier).</li><li>Schrijf bij <b>Mijn vragen</b> op wat je wilt bespreken. Onderaan zie je meteen hoe het eruitziet.</li><li>Tik op <a class=\"ho-go\" data-click=\"#kma-share-btn\"><b>Delen</b></a> om het naar je teamleider te sturen (het gaat mee met je dossier), of op <b>PDF</b> om het te bewaren of te printen.</li></ol><div class=\"call privacy\"><b>Privacy</b> Je stresscheck gaat nooit naar het CadetVolgSysteem (sinds 4.30). Wil je hem bespreken, neem dan je eigen afdruk mee.</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Voorbereiding kiezen</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Voorbeeld van je voorbereiding</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Mijlpalen</h3><ol class=\"steps\"><li>Open <a class=\"ho-go\" data-menu=\"Mijlpalen\"><b>⋮ → Mijlpalen</b></a>. Je ziet acht insignes in schildvorm. Behaalde insignes zijn goud op donkergroen; de andere zijn een gestippelde omtrek. Tik op een insigne voor uitleg.</li><li>Je haalt ze zo: <b>Eerste stap</b> (profiel ingevuld met naam, Peoplesoft-nummer en krijgsmachtdeel), <b>Reflector</b> (eerste 5G-T-reflectie), <b>Waarnemer</b> (10 DTF-feiten), <b>Volhouder</b> (4 weken op rij je SMART-check-in gelukt of deels gelukt), <b>360°</b> (drie anderen gaven feedback), <b>Kern</b> (alle kernhoofdstukken af), <b>Fit &amp; scherp</b> (drie stresschecks) en <b>Portfolio</b> (je eerste portfolio als PDF).</li><li>Haal je een insigne, dan verschijnt onderin kort een melding. Een behaald insigne blijft behaald, met de datum erbij.</li></ol><div class=\"call info\"><b>Goed om te weten</b> Insignes zijn alleen voor jezelf: er zijn geen punten en geen ranglijst, en ze komen niet in je portfolio.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>⋮ → Mijlpalen</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Kleur van je krijgsmachtdeel</h3><ol class=\"steps\"><li>Vul in <a class=\"ho-go\" data-step=\"0\">hoofdstuk 0</a> je <b>krijgsmachtdeel</b> in (CLAS, CZSK, CLRS of KMar).</li><li>De kopbalk, de streep eronder en de accentkleur van de app volgen dan je krijgsmachtdeel: groen voor de CLAS, marineblauw voor de CZSK, luchtmachtblauw voor de CLRS en blauw met oranje voor de KMar.</li><li>Het embleem van je krijgsmachtdeel staat naast het KMA-embleem bovenaan de startpagina.</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Kleur van de CZSK</figcaption></figure></div></div><div class=\"tut\"><h3>Navigeren tussen hoofdstukken</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Onder de kaart <b>Voortgang</b> staat de inhoudsopgave, in drie uitklapmenu's. <b>Vaste basis</b>: je rode draad, hiermee werk je de hele opleiding (<a class=\"ho-go\" data-step=\"0\">hoofdstuk 0</a> t/m 8, met de stappen <i>Jezelf leren kennen</i>, <i>Leervraag</i>, <i>Reflecteren</i> en <i>Doen en vastleggen</i> als kopjes). <b>Verdieping</b>: het zelfbeoordelingsformulier, de voorbereiding op de cadetbeoordeling, de probleem- en behoefteanalyse, fitheid en stress en je cv, voor rond een beoordeling, als er iets speelt of als het past (<a class=\"ho-go\" data-step=\"9\">hoofdstuk 7</a> t/m 13). <b>Naslag en overzicht</b>: toetsing en examinering, de begrippenlijst en je groei, daar hoef je niets in te vullen (<a class=\"ho-go\" data-step=\"14\">hoofdstuk 12</a> t/m 16).</li><li>Tik op een groep om de hoofdstukken eronder te zien; tik nog eens om hem dicht te klappen. Er staat steeds één groep open: klap je <b>Verdieping</b> open, dan gaat <b>Vaste basis</b> dicht. De groep waarin je nu zit, heeft een rode rand. Per hoofdstuk zie je hoeveel vragen erin staan.</li><li>Met <b>Volgende</b> loop je de hoofdstukken in deze volgorde door; onderaan staat bij een verdiepingshoofdstuk <i>Verdieping</i>.</li><li>Tik op een hoofdstuk om er direct naartoe te gaan. Op de telefoon klapt de inhoudsopgave daarna dicht, zodat je meteen bij de vragen bent; op de computer blijft de groep open. Een vinkje betekent dat het hoofdstuk af is.</li><li>Onderaan het scherm staat altijd de balk met <b>‹ Vorige</b> en <b>Volgende ›</b>, met daartussen het hoofdstuknummer en hoeveel je hebt ingevuld.</li><li>Je antwoorden worden automatisch opgeslagen terwijl je typt. Er is geen opslaan-knop nodig.</li></ol><div class=\"call tip\"><b>Tip</b> Gebruik het zoekveld bovenaan een hoofdstuk (<i>Zoek trefwoord in vragen, antwoorden &amp; begrippen</i>) om snel iets terug te vinden.</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Vaste basis opengeklapt</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Verdieping opengeklapt</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Voorbeeldantwoorden</h3><ol class=\"steps\"><li>Bij ongeveer twintig lastige vragen staat naast de vraag een klein knopje <b>Voorbeeld</b>.</li><li>Tik erop voor een kort voorbeeld van een goed antwoord. Tik nog eens om het te sluiten.</li><li>Gebruik het als idee, niet om over te nemen: je eigen woorden en voorbeelden zijn wat telt.</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Een voorbeeldantwoord</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Het menu ⋮ (meer opties)</h3><ol class=\"steps\"><li><b>Portfolio (PDF)</b>: maak een opgemaakt portfolio van al je producten (zie pagina <a class=\"ref\" href=\"#A20\">A20</a>).</li><li><b>Deelmap</b> en <b>Versleuteld delen</b>: koppel de gedeelde map en vul de groepscode van je teamleider in (zie pagina <a class=\"ref\" href=\"#A22\">A22</a>).</li><li><b>Beoordelingsformulier</b>: opent het officiële KMA-zelfbeoordelingsformulier (zie <a class=\"ho-go\" data-step=\"5\">hoofdstuk 9</a>).</li><li><b>PIN-code</b>: beveilig je antwoorden met een pincode (zie hieronder).</li><li><b>Feedback van je teamleider</b>: lees feedback in die je teamleider je stuurde, en zie bij welke hoofdstukken die staat (zie pagina <a class=\"ref\" href=\"#A24\">A24</a>).</li><li><b>Back-up maken</b> en <b>Back-up terugzetten</b>: een back-up voor jezelf, en die terugzetten, bijvoorbeeld op een nieuwe telefoon (zie pagina <a class=\"ref\" href=\"#A23\">A23</a>).</li><li><b>Weergave</b>: <i>Grotere tekst</i> en <i>Hoog contrast</i>; <i>Automatisch</i> volgt de instelling van je telefoon, of kies vast <i>Licht</i> of <i>Donker</i>.</li><li><b>Alles wissen</b>: verwijdert al je antwoorden van dit toestel. Maak eerst een back-up!</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Menu ⋮</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Je antwoorden beveiligen met een PIN-code</h3><ol class=\"steps\"><li>Open <a class=\"ho-go\" data-menu=\"PIN-code\"><b>⋮ → PIN-code</b></a>.</li><li>Tik je 4-cijferige code in op het <b>cijferpaneel</b> en tik op <b>PIN opslaan</b>. Het toetsenbord van je telefoon hoeft niet open.</li><li>Vanaf nu vraagt de app om je PIN bij het openen, en opnieuw als de app langer dan 2 minuten op de achtergrond stond. Na 4 cijfers gaat de app vanzelf open; met ⌫ wis je een cijfer.</li><li>Wil je de PIN wijzigen of uitzetten, open dan hetzelfde scherm en kies <b>PIN verwijderen</b>.</li></ol><div class=\"call let\"><b>Let op</b> Na 5 foute pogingen moet je even wachten, en die wachttijd wordt steeds langer. Vergeet je je PIN, dan kun je je antwoorden niet meer openen. Bewaar je code dus goed en maak regelmatig een back-up.</div><div class=\"call privacy\"><b>Privacy</b> Alles wat je in de app invult, wordt versleuteld op je telefoon opgeslagen. Wie de bestanden van je telefoon kopieert, kan ze niet lezen.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Pincode met het cijferpaneel</figcaption></figure></div></div><div class=\"tut\"><h3>Terug, vragen en meldingen (sinds 4.6.0)</h3><ol class=\"steps\"><li><b>Vegen</b>: een menu of venster dat van onderen opkomt, sluit je ook door het naar beneden te vegen (sinds 4.8.1). Linksonder verschijnt <b>Naar boven</b> als je ver bent gescrold.</li><li><b>Terug</b>: met de terugknop van je Android-telefoon sluit je eerst een open menu of venster; daarna ga je terug naar het hoofdstuk waar je vandaan kwam, en uiteindelijk naar het begin. Op het begin sluit de terugknop de app.</li><li>Op de <b>iPhone en iPad</b> doe je hetzelfde door vanaf de linkerrand van het scherm naar rechts te vegen.</li><li>Vraagt de app iets (bijvoorbeeld <i>Dit DTF-feit verwijderen?</i>), dan staan er duidelijke knoppen onder, zoals <b>Annuleren</b> en <b>Verwijderen</b>. Een rode knop betekent dat je iets weghaalt.</li><li>Vink je iets af (een check-in <b>Gelukt</b>, feedback <b>Verwerkt</b>), dan tekent zich even een groen vinkje.</li></ol><div class=\"call tip\"><b>Tip</b> Staat op je telefoon <b>Beweging beperken</b> (iPhone) of <b>Animaties verwijderen</b> (Android) aan, dan laat de app alle bewegingen weg.</div></div><div class=\"tut\"><h3>Vragen beantwoorden</h3><ol class=\"steps\"><li>Tik in een antwoordveld en typ je antwoord. Het veld groeit mee met je tekst.</li><li>Liever praten? Tik op het <b>microfoon-icoon</b> in het veld en spreek je antwoord in; de tekst verschijnt vanzelf.</li><li>Vragen met <b>[Verdieping]</b> zijn extra vragen om dieper na te denken. Ze tellen mee voor je voortgang.</li><li>Een groen vinkje naast <b>VRAAG 01</b> betekent dat die vraag is beantwoord.</li></ol></div><section class=\"sec\" id=\"A1b\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Samenhang: volgende stap en begrippen</h2><p class=\"lead\">De hoofdstukken horen bij elkaar. De app helpt je de route te volgen en vakbegrippen te begrijpen.</p><div class=\"tut row\"><div class=\"txt\"><h3>Volgende stap</h3><ol class=\"steps\"><li>Onderaan elk hoofdstuk staat een kaart <b>Volgende stap</b> met het hoofdstuk dat logisch volgt, en waarom.</li><li>Staat erbij <b>Nog niet begonnen</b>, dan heb je in dat hoofdstuk nog niets ingevuld.</li><li>Tik op <b>Ga verder</b> om er direct naartoe te gaan. Je kunt natuurlijk ook je eigen volgorde kiezen.</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Volgende stap onder een hoofdstuk</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Begrippen aantikken</h3><ol class=\"steps\"><li>Woorden die in je begrippenlijst (<a class=\"ho-go\" data-step=\"12\">hoofdstuk 15</a>) staan, zijn in de andere hoofdstukken met een stippellijn onderstreept.</li><li>Tik op zo'n woord: je ziet de uitleg in een klein venster. Met <b>Begrippenlijst</b> ga je naar de hele lijst.</li><li>Voeg je zelf een begrip toe aan je begrippenlijst, dan wordt dat ook overal onderstreept.</li></ol><div class=\"call info\"><b>Goed om te weten</b> Begrippen worden nooit gemarkeerd in tekstvakken waar je zelf typt.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Uitleg van een begrip</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Handig om te weten</h3><ol class=\"steps\"><li><b>+ Nieuw</b> (rechtsonder, op elk scherm): leg direct een <b>DTF-feit</b> vast of begin een nieuwe <b>5G-T</b>- of <b>Korthagen</b>-reflectie.</li><li><b>Voorbeeld</b>: bij de stappen van 5G-T en Korthagen en bij een DTF-feit kun je een goed en een minder goed voorbeeld openklappen.</li><li><b>Concept</b>: een DTF-feit dat je nog niet opsloeg, blijft bewaard. De app zet het terug als je terugkomt. 5G-T en Korthagen openen bij de stap waar je was.</li><li>In de hoofdstukkenlijst laat een <b>rondje</b> zien of een hoofdstuk leeg, half of klaar is; <b>nieuw</b> betekent dat er nieuwe feedback van je teamleider staat.</li><li><b>Zoeken</b>: het zoekveld zoekt in je hele boekje (antwoorden, DTF, reflecties, levenslijn, plannen, fitheid en begrippen). Je vindt het ook via <a class=\"ho-go\" data-menu=\"Zoeken in je boekje\"><b>⋮ → Zoeken in je boekje</b></a>. Tik op een resultaat om ernaartoe te gaan.</li><li><b>Ongedaan maken</b>: verwijder je een feit, reflectie, meting, begrip, als-dan-plan of ontvangen feedback, dan kun je dat een paar seconden lang terugdraaien.</li><li>Tik op een <u>onderstreept</u> begrip zoals DTF, NTB of SWOT voor een korte uitleg.</li><li>Bij <b>⋮ → Weergave</b> zet je <b>Grotere tekst</b> en <b>Hoog contrast</b> aan.</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Zoeken in je hele boekje</figcaption></figure></div></div><section class=\"sec\" id=\"A2\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Hoofdstuk 0 · Cadet Informatie &amp; Profiel</h2><button type=\"button\" class=\"ho-open\" data-step=\"0\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Hier vul je je persoonsgegevens in. Je teamleider ziet deze gegevens bovenaan je dossier in het CadetVolgSysteem.</p><div class=\"tut row\"><div class=\"txt\"><h3>Je profiel invullen</h3><ol class=\"steps\"><li>Vul je <b>voor- en achternaam</b> in. Bovenaan verschijnt meteen je <b>ID-kaart</b>: zo ziet je teamleider jou in het CadetVolgSysteem.</li><li>Vul je <b>Peoplesoft-nummer</b> in. De app waarschuwt als je iets anders dan cijfers typt.</li><li>Kies je <b>OPCO</b> (krijgsmachtdeel: CLAS, CZSK, CLRS, KMar …) uit de lijst. Op je ID-kaart verschijnt dan het symbool van je krijgsmachtdeel.</li><li>Tik op <b>Kies foto</b> om een pasfoto in uniform toe te voegen. Je kiest een foto uit je galerij of maakt er direct een met de camera. De app verkleint de foto automatisch, zodat delen snel blijft.</li></ol><div class=\"call tip\"><b>Tip</b> Gebruik dezelfde naam en hetzelfde Peoplesoft-nummer als je teamleider kent. Daaraan herkent het CadetVolgSysteem je dossier wanneer je een update stuurt.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>ID-kaart en pasfoto</figcaption></figure></div></div><div class=\"tut\"><h3>Je opleiding: burger of doorstromer (sinds 4.30)</h3><ol class=\"steps\"><li>Onder je gegevens staat het blok <b>Je opleiding</b>. Kies <b>Ik begin in week 1</b> als je als burger aan de opleiding van 35 weken begint, of <b>Ik ben doorstromer (instroom week 8)</b> als je al militair bent.</li><li>Vul je <b>startdatum</b> in: je eerste dag op de KMA. De app telt dan de opleidingsweek (bijvoorbeeld <i>week 10 van 35 · jouw 3e week</i>) en je meetmomenten vanaf jouw start.</li><li><b>Geslacht</b> is vrijwillig en alleen nodig als je meedoet aan het onderzoek. Kies <i>Zeg ik liever niet</i> als je het niet wilt invullen.</li></ol><div class=\"call privacy\"><b>Privacy</b> Je geslacht gaat nooit naar je teamleider of het CadetVolgSysteem. In het onderzoek wordt het alleen over alle cadetten samen bekeken, nooit per peloton. Instroom en startdatum gaan wel mee als je deelt.</div><div class=\"call info\"><b>Goed om te weten</b> Had je al een profiel? Dan staat je instroom op <i>burger</i> zonder startdatum. Pas het aan als het anders is; verder verandert er niets.</div></div><section class=\"sec\" id=\"A3\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Hoofdstuk 1 · Introductie &amp; Drijfveren</h2><button type=\"button\" class=\"ho-open\" data-step=\"1\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Over je achtergrond, je gezin en je woonsituatie. Omdat dit persoonlijk is, staat dit hoofdstuk standaard op <b>privé</b>.</p><div class=\"tut row\"><div class=\"txt\"><h3>Privé of gedeeld</h3><ol class=\"steps\"><li>Onder de hoofdstuktitel staat de schakelaar <b>Privé, niet gedeeld</b>.</li><li>Zolang de schakelaar uit staat, worden je antwoorden in dit hoofdstuk <b>niet</b> meegestuurd als je je dossier deelt.</li><li>Wil je dat je teamleider dit hoofdstuk wél kan lezen, zet de schakelaar dan aan. Je kunt dit altijd weer terugzetten.</li></ol><div class=\"call privacy\"><b>Privacy</b> Bijna elk hoofdstuk heeft zo'n schakelaar. <i>Introductie &amp; Drijfveren</i> en je <i>cv</i> staan standaard op privé, de rest wordt standaard gedeeld. <i>Fitheid &amp; stress</i> is altijd privé en heeft geen schakelaar (zie <a class=\"ref\" href=\"#A14\">A14</a>).</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Privé-schakelaar</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Je steuncirkel</h3><ol class=\"steps\"><li>Typ bij <b>Jouw steuncirkel</b> de naam of rol van iemand die je steunt (bijvoorbeeld <i>Moeder</i>, <i>Vriendin Lisa</i>, <i>Coach voetbal</i>).</li><li>Kies hoe dichtbij die persoon staat: <i>Heel dichtbij</i>, <i>Dichtbij</i> of <i>Verder weg</i>.</li><li>Tik op <b>+ Toevoegen</b>. De persoon verschijnt als stip in de cirkel: hoe dichter bij het midden, hoe meer steun.</li><li>Tik op het kruisje bij een naam om iemand te verwijderen.</li></ol><div class=\"call tip\"><b>Tip</b> De steuncirkel helpt in gesprekken over belastbaarheid: bij wie kun je terecht als het zwaar wordt tijdens de opleiding? Bij een hoge stressscore noemt de app deze mensen ook (zie <a class=\"ref\" href=\"#A14\">A14</a>).</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Steuncirkel</figcaption></figure></div></div><section class=\"sec\" id=\"A4\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Hoofdstuk 2 · Ontwikkelbiografie Tijdlijn</h2><button type=\"button\" class=\"ho-open\" data-step=\"2\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Breng de belangrijkste momenten uit je leven in kaart en ontdek welke kwaliteiten steeds terugkomen.</p><div class=\"tut\"><h3>Je levenslijn maken</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>De levenslijn staat altijd klaar. Tik op de plek in de lijn waar iets belangrijks gebeurde: links-rechts is het <b>jaar</b>, hoger is een <b>hoogtepunt</b>, lager een <b>dieptepunt</b>. Je kunt ook op <b>+ Gebeurtenis toevoegen</b> tikken.</li><li>Er opent een kaartje met het jaar en de score van de plek waar je tikte. Typ kort <b>wat er gebeurde</b> en pas het jaar of de schuif (−5 tot +5) eventueel aan.</li><li>Tik de <b>kwaliteiten</b> aan die je bij dit moment hielpen, zoals Doorzettingsvermogen of Leiderschap.</li><li>Tik op <b>Toevoegen</b>. De gebeurtenis verschijnt als punt op je levenslijn en in de lijst eronder.</li><li>Tik op een punt of op een gebeurtenis in de lijst om hem aan te passen of te verwijderen.</li><li>Onder de grafiek staat <b>Jouw rode draad</b>: de kwaliteiten die het vaakst terugkomen.</li></ol><div class=\"call tip\"><b>Tip</b> Neem ook de dieptepunten op. Juist daar zie je vaak welke kwaliteiten je verder hielpen: dat is goed materiaal voor de vragen in dit hoofdstuk.</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Levenslijn en rode draad</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Gebeurtenis toevoegen</figcaption></figure></div></div><section class=\"sec\" id=\"A5\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Hoofdstuk 3 · Persoonlijkheidstest</h2><button type=\"button\" class=\"ho-open\" data-step=\"3\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Een test met 96 korte stellingen (kort) of 240 (lang) die zes eigenschappen meet: Integriteit, Emotionaliteit, Extraversie, Verdraagzaamheid, Consciëntieusheid en Openheid. Daarna laat je 2 tot 4 mensen die je goed kennen dezelfde stellingen over jou invullen (360°).</p><div class=\"tut\"><h3>De test maken</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Tik op <b>Start de test</b>. Je krijgt één stelling per scherm.</li><li>Kies het antwoord dat het best bij je past: <i>Helemaal oneens</i> tot <i>Helemaal eens</i>. Je gaat automatisch naar de volgende stelling.</li><li>Twijfel je? Kies wat in de meeste situaties klopt. Er zijn geen goede of foute antwoorden.</li><li>Tik op <b>Vorige</b> om een antwoord te wijzigen, of op <b>Sla over</b> om later terug te komen.</li><li>Even geen tijd? Tik op <b>✕ Pauzeren</b>. Je antwoorden worden bewaard en je gaat later verder met <b>Ga verder bij stelling …</b></li></ol><div class=\"call info\"><b>Goed om te weten</b> De korte test duurt ongeveer 12 minuten, de lange 30 tot 40 minuten. De stellingen komen uit de International Personality Item Pool (IPIP), een vrij te gebruiken vragenbank.</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Voor de test</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Eén stelling per scherm</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Je resultaat lezen</h3><ol class=\"steps\"><li>Na de laatste stelling zie je je <b>profiel</b>: een zeshoek met je score per eigenschap (0-100%).</li><li>Bovenaan staan je hoogste en laagste eigenschap.</li><li>Tik bij <b>Jouw zes eigenschappen</b> op een eigenschap voor uitleg. De balk loopt van de ene pool (bijv. <i>kalm, onbewogen</i>) naar de andere (<i>gevoelig, betrokken</i>).</li><li>Een score is geen oordeel: beide kanten hebben sterke punten en valkuilen.</li></ol><div class=\"call let\"><b>Let op</b> De uitslag is een indicatie om over te praten, geen meting of beoordeling. Bespreek hem met je teamleider.</div><div class=\"call info\"><b>Goed om te weten</b> Sinds versie 4.7.0 controleert de app of de test met aandacht is ingevuld: niet heel snel (minder dan 2 seconden per stelling), niet steeds hetzelfde antwoord, en geen tegenstrijdige antwoorden op stellingen die bij elkaar horen. Is dat zo, dan staat boven je uitslag dat die mogelijk minder betrouwbaar is. Je scores veranderen daardoor niet; lees de stellingen rustig opnieuw en pas aan waar nodig.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Profiel en eigenschappen</figcaption></figure></div></div><div class=\"tut\"><h3>360°: anderen laten invullen</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Typ bij <b>360°: hoe anderen jou zien</b> de naam van iemand die je goed kent en kies de rol (Mede-cadet, Teamleider, …). Tik op <b>+ Toevoegen</b>.</li><li>Je ziet het scherm <b>Geef de telefoon aan …</b>. Geef je telefoon aan die persoon; hij of zij tikt op <b>Start</b>.</li><li>De observator beantwoordt dezelfde stellingen, maar dan over jou (<i>Hij/zij houdt dingen netjes</i>).</li><li>Na afloop vraagt de app om de telefoon terug te geven. In het overzicht staat de observator nu op <b>klaar</b>.</li><li>Doe dit met 2 tot 4 mensen. De app toont het gemiddelde van al je observatoren.</li></ol><div class=\"call privacy\"><b>Privacy</b> Observatoren zien jouw eigen antwoorden niet. Hun antwoorden worden alleen in jouw Reflectieboekje bewaard.</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Observatoren beheren</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Overdrachtscherm</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Zelfbeeld en hoe anderen je zien</h3><ol class=\"steps\"><li>Zodra er observatoren zijn, verschijnt hun gemiddelde als blauwe stippellijn in de zeshoek en als blauw streepje op elke eigenschapsbalk.</li><li>Onder <b>Zelfbeeld en hoe anderen je zien</b> staan de grootste verschillen:</li><li><b>Verborgen kracht</b> (groen): anderen zien méér van deze eigenschap dan jij zelf.</li><li><b>Mogelijke blinde vlek</b> (rood): jij ziet jezelf hoger dan anderen je zien.</li><li><b>Wisselend beeld</b>: je observatoren zijn het onderling niet eens. Vraag ze wat ze zien.</li></ol><div class=\"call tip\"><b>Tip</b> Een blinde vlek is geen fout. Het is een goed gespreksonderwerp: vraag je observatoren om een concreet voorbeeld.</div><div class=\"call let\"><b>Let op</b> Eerlijk gezegd: 360°-feedback verandert op zichzelf weinig. Onderzoek laat gemiddeld maar een kleine verbetering zien, en alleen bij mensen die de feedback serieus nemen, er een doel van maken en er echt iets mee doen (Smither, London en Reilly, 2005). Daarom eindigt de uitslag met <b>Van feedback naar actie</b>: zet één punt in je leervraag, maak een als-dan-plan en doe een check-in na de situatie. Bespreek het daarna met je teamleider.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Verschillen</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Vertaling naar de 4 V's en je SWOT</h3><ol class=\"steps\"><li>Bij <b>Vertaling naar de 4 V's</b> zie je een <i>indicatie</i> van hoe je profiel aansluit bij Verbondenheid, Veiligheid, Vertrouwen en Verantwoordelijkheid, in drie banden: <b>aandachtspunt</b>, <b>gemiddeld</b> of <b>sterk</b>. Tik op <b>Hoe komt dit tot stand?</b> voor de berekening met jouw eigen scores en de bronnen.</li><li>Bij <b>Jouw SWOT</b> maakt de app op basis van je scores maximaal drie punten per vak: Sterke kanten, Valkuilen, Kansen en Bedreigingen. Bij elk punt staat waarom (<i>omdat je hoog scoort op …</i>).</li><li>Bij een valkuil staat een <b>Probeer dit</b>-suggestie.</li><li>Tik op <b>Maak SMART-leervraag</b> om direct een leervraag te starten vanuit dit punt (<a class=\"ho-go\" data-step=\"7\">hoofdstuk 5</a>).</li></ol><div class=\"call let\"><b>Let op</b> De koppeling met de 4 V's en de SWOT-teksten zijn gebaseerd op onderzoek naar persoonlijkheid en werk, maar zijn zelf nog niet onderzocht. Gebruik ze als begin van een gesprek, niet als oordeel. Ze tellen niet mee voor je beoordeling.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>SWOT</figcaption></figure></div></div><div class=\"tut\"><h3>Kort of lang kiezen (sinds 4.30)</h3><ol class=\"steps\"><li>Bovenaan het hoofdstuk kies je <b>Kort · 96 stellingen</b> (ongeveer 12 minuten) of <b>Lang · 240 stellingen</b> (30 tot 40 minuten). De korte test zit in de lange: begin je kort, dan kun je later de 144 extra stellingen alsnog maken met <b>Start de 144 extra stellingen</b>.</li><li>Kies je lang, dan tik je op <b>Start de lange test</b>. De teller loopt tot 240: deel 1 zijn de 96 stellingen, daarna opent deel 2 met de 144 extra vanzelf. Je kunt pauzeren; wat je invult blijft bewaard.</li><li>De lange test geeft een kleinere meetfout. Dat zie je in de uitslag aan een smallere lichte band en aan een betrouwbaardere groeilijn.</li></ol><div class=\"call privacy\"><b>Privacy</b> Je uitslag is standaard <b>privé</b>: je deelt hem niet met je teamleider tot je dat zelf aanzet. Deelde je hem al eens, dan blijft dat zo. Je uitslag telt nooit mee voor je beoordeling.</div></div><div class=\"tut\"><h3>Waar sta je ten opzichte van anderen?</h3><ol class=\"steps\"><li>Onder je profiel staat per eigenschap een <b>klokcurve</b>: de verdeling in de normgroep. Het gekleurde deel zijn de mensen die lager scoren dan jij; de streep ben jij.</li><li>Eronder lees je bijvoorbeeld <i>Je scoort hoger dan 74 van de 100 mensen in de normgroep</i> en een band: <b>zeer laag</b>, <b>laag</b>, <b>gemiddeld</b>, <b>hoog</b> of <b>zeer hoog</b>.</li><li>Staat er <b>grensgeval</b>, dan ligt je score minder dan één meetfout van een andere band. Lees de band dan als een indicatie, niet als een vast oordeel.</li></ol><div class=\"call info\"><b>Goed om te weten</b> De normgroep is de IPIP-HEXACO-steekproef van openpsychometrics.org (20.365 mensen, internationaal, online). Het zijn geen cadetten. Zodra de KMA genoeg eigen gegevens heeft, komt er een KMA-norm.</div></div><div class=\"tut\"><h3>Metingen en je groeilijn</h3><ol class=\"steps\"><li>Onder je SWOT staat <b>Metingen</b> met drie meetmomenten: <b>begin</b> (je eerste drie weken), <b>midden</b> (rond week 21) en <b>eind</b> (rond week 33). Doorstromers beginnen in week 8; de app rekent vanaf jouw startdatum.</li><li>Is het tijd voor een meting, dan staat er een taak in <b>Vandaag</b>. Tik op <b>Nieuwe meting: kort</b> of <b>Nieuwe meting: lang</b>. Je vorige antwoorden blijven bewaard bij je metingen.</li><li>Na twee metingen zie je per eigenschap de oude en nieuwe score. Alleen een verschil groter dan de meetfout heet <b>echt hoger</b> of <b>echt lager</b>; de rest is <i>binnen de meetfout</i>.</li></ol><div class=\"call tip\"><b>Tip</b> Maak bij het begin en het eind de lange test: dan is de groeilijn het betrouwbaarst.</div></div><div class=\"tut\"><h3>Je SWOT met bewijs</h3><ol class=\"steps\"><li>Bij elk punt van je SWOT staat nu wat het onderbouwt: <b>bevestigd: 2 DTF-feiten</b> als je minstens twee DTF-feiten aan die sterkte of valkuil koppelde, of wat je observatoren zien. Is er nog niets, dan staat er eerlijk <i>nog te weinig gegevens</i>.</li><li>Onder elk punt staat een korte <b>bron</b> uit het onderzoek, bijvoorbeeld <i>Barrick en Mount (1991): consciëntieusheid voorspelt prestaties in alle beroepen</i>.</li><li>Bij de 360°-feedback staat bovenaan in één zin het grootste verschil tussen jouw beeld en dat van anderen. De labels <b>blinde vlek</b> en <b>verborgen kracht</b> verschijnen pas vanaf drie observatoren.</li></ol><div class=\"call tip\"><b>Tip</b> Kies minstens één observator buiten je vriendengroep: dat geeft een eerlijker beeld. Je teamleider kan iemand voorstellen.</div></div><section class=\"sec\" id=\"A6\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Hoofdstuk 4 · Ik en de Gedragscode Defensie</h2><button type=\"button\" class=\"ho-open\" data-step=\"4\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Wat de vier kernwaarden van de Gedragscode Defensie (de 4 V's) betekenen, en hoe jij ze in je gedrag laat zien. Je leest eerst wat de 4 V's zijn, beantwoordt dan de vragen en geeft jezelf tot slot per V een score.</p><div class=\"tut row\"><div class=\"txt\"><h3>1 · Wat zijn de 4 V's?</h3><ol class=\"steps\"><li>Bovenaan staat per V de zin uit de <b>Gedragsregels Defensie</b>, met het pictogram van het beoordelingsformulier. Bijvoorbeeld bij Verbondenheid: <i>Ik werk samen, help anderen, sta open voor feedback en spreek aan.</i></li><li>Eronder staat in één zin wat dat in de praktijk betekent.</li><li>Tik op <b>Waar let je teamleider op? (niveau 1)</b> voor het gedrag dat bij die V op het KMA-beoordelingsformulier staat.</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>De 4 V's uitgelegd</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>2 · De vragen</h3><ol class=\"steps\"><li>De vragen zijn verdeeld over tabbladen: <b>Algemeen</b> en één tab per V, elk met het pictogram van die V.</li><li>Op elke tab zie je hoeveel vragen je al hebt beantwoord (bijv. <i>Vertrouwen 0/4</i>).</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Vragen per V</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>3 · De 4 V's in één oogopslag</h3><ol class=\"steps\"><li>Onder de vragen geef je jezelf per V een score van 1 tot 10 met de schuifbalk. De scores beginnen leeg: <i>Nog niet gescoord</i>.</li><li>Onder elke score zie je ter vergelijking de indicatie uit je persoonlijkheidstest en hoeveel <b>DTF-feiten</b> je voor die V hebt verzameld.</li><li>Met <b>Zelfbeoordelingsformulier</b> ga je direct door naar <a class=\"ho-go\" data-step=\"5\">hoofdstuk 9</a>.</li></ol><div class=\"call tip\"><b>Tip</b> Heb je voor een V nog geen DTF-feiten? Let er de komende week bewust op en leg voorbeelden vast in je DTF-logboek (<a class=\"ho-go\" data-step=\"11\">hoofdstuk 8</a>).</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Scores per V</figcaption></figure></div></div><section class=\"sec\" id=\"A7\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Hoofdstuk 5 · SMART Leervraag</h2><button type=\"button\" class=\"ho-open\" data-step=\"7\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Formuleer je persoonlijke ontwikkeldoel volgens SMART: Specifiek, Meetbaar, Acceptabel, Realistisch en Tijdgebonden. Bovenaan het hoofdstuk staat: <i>Vul de onderstaande vragen in om je SMART Leervraag op te stellen.</i></p><div class=\"tut row\"><div class=\"txt\"><h3>Je leervraag bouwen</h3><ol class=\"steps\"><li>Het hoofdstuk staat in deze volgorde: <b>Mijn leervraag</b>, <b>Jouw leervraag in één zin</b>, direct daaronder de <b>vijf SMART-vragen</b>, dan je <b>als-dan-plannen</b>, de <b>wekelijkse check-in</b> en het <b>bewijs</b>.</li><li>Beantwoord de vijf vragen (één per letter). In <b>Jouw leervraag in één zin</b>, net boven de vragen, bouwt de app terwijl je typt één zin uit je antwoorden.</li><li>Elke letter (S-M-A-R-T) kleurt zodra dat onderdeel is ingevuld.</li><li>Kies een <b>evaluatiedatum</b> en tik op <b>Zet in agenda</b>. De app maakt een agenda-afspraak die je in je telefoonagenda kunt openen.</li><li>Weet je niet waar je moet beginnen? Tik op een van de <b>Startpunten uit je persoonlijkheidstest</b>.</li></ol><div class=\"call tip\"><b>Tip</b> Een goede leervraag gaat over zichtbaar gedrag: <i>Ik geef in elk groepsoverleg minstens één keer als eerste mijn mening</i> is beter dan <i>Ik wil assertiever worden</i>.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>SMART-zin en letters</figcaption></figure></div></div><div class=\"tut\"><h3>Meerdere leervragen</h3><ol class=\"steps\"><li>Bovenaan het hoofdstuk staat <b>Mijn leervraag</b>. Klaar met je leervraag? Tik op <b>Leervraag voltooien</b>, schrijf kort wat je hebt bereikt en wat je meeneemt, en tik nog eens op <b>Leervraag voltooien</b>.</li><li>Tik op <b>Nieuwe leervraag</b> om een volgende te beginnen. De vorige blijft bewaard, met zijn antwoorden, plannen en check-ins.</li><li>Heb je meer dan één leervraag, dan staan ze als tabbladen bovenaan. Tik op een tabblad om te wisselen; een vinkje betekent voltooid.</li><li>Een voltooide leervraag kun je lezen maar niet meer wijzigen. Met <b>Heropenen</b> werk je er weer aan.</li><li>Deel je dit hoofdstuk, dan ziet je teamleider ook je andere leervragen, met je terugblik.</li></ol></div><div class=\"tut row\"><div class=\"txt\"><h3>Doel in vijf niveaus</h3><ol class=\"steps\"><li>Onder de vijf SMART-vragen staat <b>Doel in vijf niveaus</b>. Beschrijf eerst niveau <b>0</b>: wat je op je einddatum ziet als het precies lukt, bijvoorbeeld <i>In 4 van de 5 briefings noem ik eerst het doel</i>.</li><li>Beschrijf daarna <b>−2</b> (veel minder dan verwacht, vaak waar je nu staat), <b>−1</b>, <b>+1</b> en <b>+2</b> (veel meer dan verwacht). Tik op <b>Niveaus opslaan</b>.</li><li>Tik af en toe bij <b>Waar sta je nu?</b> op je niveau. Per week telt één keuze; de grafiek toont je groei.</li><li>Met <b>Niveaus aanpassen</b> verander je de beschrijvingen. De niveaus horen bij je leervraag: een nieuwe leervraag begint leeg.</li></ol><div class=\"call tip\"><b>Tip</b> Maak de stappen tussen de niveaus ongeveer even groot en beschrijf zichtbaar gedrag, net als bij je leervraag.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Doel in vijf niveaus</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Wat houdt je tegen?</h3><ol class=\"steps\"><li>Onder de niveaus staat <b>Wat houdt je tegen?</b>. Beschrijf eerst <b>het mooiste resultaat als het lukt</b>.</li><li>Beschrijf daarna <b>het belangrijkste obstakel in jezelf</b>: niet de omstandigheden, maar wat jij doet of denkt, bijvoorbeeld <i>ik wil snel beginnen en sla de uitleg over</i>.</li><li>Tik op <b>Maak er een als-dan-plan van</b>. Het obstakel staat dan al bij <b>Als</b>; vul zelf in wat je dan doet.</li></ol><div class=\"call info\"><b>Goed om te weten</b> Eerst het resultaat voor je zien en daarna het obstakel benoemen werkt beter dan alleen een doel stellen (WOOP: Wish, Outcome, Obstacle, Plan).</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Wat houdt je tegen?</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Wekelijkse check-in</h3><ol class=\"steps\"><li>Onder je SMART-zin staat <b>Wekelijkse check-in</b>. Tik elke week op <b>Gelukt</b>, <b>Deels</b> of <b>Niet gelukt</b> en schrijf eventueel kort wat hielp of wat je tegenhield.</li><li>Per week is er één check-in; tik je opnieuw, dan pas je die van deze week aan.</li><li>De bolletjes laten de laatste 12 weken zien: groen gelukt, geel deels, rood niet gelukt. Eronder staat hoeveel weken op rij het (deels) lukte.</li><li>Deel je dit hoofdstuk, dan ziet je teamleider de check-ins ook; ze staan ook in je gesprekssamenvatting.</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Check-in en tijdlijn</figcaption></figure></div></div><div class=\"tut\"><h3>Check-in direct na de situatie</h3><ol class=\"steps\"><li>Is de situatie uit je als-dan-plan net gebeurd? Tik op <b>+ → Als-dan-plan: is het gelukt?</b> of bij het plan op <b>Net gebeurd: gelukt?</b>, en kies <b>Gelukt</b>, <b>Deels</b> of <b>Niet</b>.</li><li>Zo leg je het vast terwijl je het nog weet. Het telt mee als check-in van deze week; de laatste van de week telt.</li><li>Heb je een leervraag maar nog geen als-dan-plan, dan herinnert <b>Vandaag</b> je eraan. Een leervraag werkt pas echt met minstens één plan.</li></ol><div class=\"call info\"><b>Goed om te weten</b> Een als-dan-plan (Als ..., dan ...) maakt de kans dat je doet wat je wilt ongeveer twee keer zo groot (Gollwitzer en Sheeran, 2006), vooral als je het doel zelf belangrijk vindt.</div></div><div class=\"tut row\"><div class=\"txt\"><h3>Bewijs bij je leervraag</h3><ol class=\"steps\"><li>Onder je check-in staat <b>Bewijs bij je leervraag</b>: alle DTF-feiten, 5G-T- en Korthagen-reflecties die je aan je leervraag hebt gekoppeld.</li><li>Koppelen doe je in het DTF-logboek en bij een reflectie met de knop <b>Bij mijn leervraag</b>. Tik nog een keer om de koppeling weer weg te halen.</li><li>Bovenaan zie je hoeveel feiten en reflecties er bij je leervraag horen. Tik op een item om het te openen.</li><li>Deel je je dossier, dan ziet je teamleider dit bewijs ook bij je leervraag.</li></ol><div class=\"call tip\"><b>Tip</b> Koppel vooral feiten die laten zien dat je leervraag lukt of nog niet lukt. Zo heb je in je beoordelingsgesprek meteen concrete voorbeelden.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Bewijs bij je leervraag</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Startpunten uit je andere hoofdstukken</h3><ol class=\"steps\"><li>Onder het bewijs staat <b>Startpunten uit je andere hoofdstukken</b>. Je ziet daar voorstellen uit je probleemanalyse (de intentie uit fase 3), een blinde vlek uit je 360°-feedback en de feedback en ontwikkelplannen van je teamleider.</li><li>Tik op een startpunt: de tekst komt bij de eerste vraag (<i>wat precies</i>) te staan.</li><li>Maak het daarna specifiek en meetbaar met de andere vragen.</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Startpunten voor je leervraag</figcaption></figure></div></div><div class=\"tut\"><h3>De gereedschapskist (sinds 4.30)</h3><ol class=\"steps\"><li>De vaste basis (<a class=\"ho-go\" data-step=\"0\">hoofdstuk 0</a> tot en met 10) doe je altijd. Daarnaast kies je zelf wat je erbij gebruikt: open <a class=\"ho-go\" data-menu=\"Gereedschapskist\"><b>⋮ → Gereedschapskist</b></a>.</li><li>Vink aan wat je wilt gebruiken: <b>Wat houdt je tegen? (WOOP)</b> en <b>Doel in vijf niveaus</b> verschijnen dan bij je SMART-leervraag, de <b>Roos van Leary</b> in je werkboek en de <b>Nabespreking</b> in + en ⋮.</li><li>Raadt je teamleider een model aan, dan staat er <b>Aangeraden door je teamleider</b>. Lukt je als-dan-plan twee keer niet helemaal, dan stelt de app WOOP voor.</li><li>Uitzetten kan altijd. Wat je al invulde blijft bewaard en komt terug als je het weer aanzet.</li></ol><div class=\"call info\"><b>Goed om te weten</b> Gebruikte je WOOP, doel in vijf niveaus, de roos of de nabespreking al voor deze versie? Dan staat dat model vanzelf aan.</div></div><section class=\"sec\" id=\"A8\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Hoofdstuk 6 · Zelfreflectie Leervraag (5G-T)</h2><button type=\"button\" class=\"ho-open\" data-step=\"8\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Reflecteer op een concrete situatie met het 5G-T-reflectiemodel van de KMA, in vier stappen: <b>1. 5G</b> (Gebeurtenis, Gevoel, Gedachtes, Gedrag, Gevolg), <b>2. Verdieping in gedachte</b>, <b>3. Invloed</b> en <b>4. Toekomst</b>.</p><div class=\"tut\"><h3>Stap 1 · 5G</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Tik op <b>+ Nieuw</b> voor een nieuwe reflectie, of op <b>Vanuit DTF-feit</b> om te starten met een feit uit je logboek. Geef de reflectie een titel.</li><li>De <b>keten</b> bovenaan (G1 tot en met G5, V, I, T) laat zien waar je bent en welke stappen klaar zijn. Tik op een bolletje om er direct naartoe te gaan.</li><li><b>Gebeurtenis</b>: beschrijf in volgorde wat er feitelijk gebeurde, zo objectief mogelijk.</li><li><b>Gevoel</b>: kies eerst <b>Vooraf</b>, <b>Tijdens</b> of <b>Achteraf</b>. Tik in het <b>emotiewiel</b> de emotie aan die het beste past (Angst, Verdriet, Woede of Vreugde, en daarbinnen bijvoorbeeld Onzeker of Trots). Kies eronder het precieze woord, zet de <b>intensiteit</b> (1-10) en tik op <b>Voeg emotie toe</b>.</li><li><b>Gedachtes</b>: schrijf in de ik-vorm wat je dacht. Met de knoppen <b>+ Vooraf / + Tijdens / + Achteraf</b> begin je een nieuwe regel voor dat moment.</li><li><b>Gedrag</b>: wat deed je feitelijk, verbaal en non-verbaal?</li><li><b>Gevolg</b>: wat was het effect? Tik de V's aan waarop je gedrag invloed had en schrijf per V kort hoe.</li></ol></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Gevoel met het emotiewiel</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Gevolg en invloed op de 4 V's</figcaption></figure></div></div><div class=\"tut\"><h3>Stap 2 · Verdieping in gedachte</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Kies je <b>belangrijkste gedachte</b>. De app laat je gedachtes uit stap 1 zien; tik er een aan om hem over te nemen.</li><li>Geef met de schuif aan hoe <b>geloofwaardig</b> die gedachte is (0-100%).</li><li>Beantwoord de vragen: welke bewijzen maken de gedachte waar en welke niet, wat is het ergste dat kan gebeuren, kun je daar overheen komen, wat zijn de voor- en nadelen, is er een andere kijk, wat zou je tegen een vriend zeggen en wat zou een vriend tegen jou zeggen?</li><li>Sluit af met een <b>alternatieve gedachte</b>.</li><li>Geef daarna opnieuw aan hoe geloofwaardig je oorspronkelijke gedachte <b>nu</b> is. Twee balkjes laten zien hoeveel je er nu minder (of meer) in gelooft dan vooraf.</li></ol></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Verdieping in gedachte</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Geloofwaardigheid vooraf en nu</figcaption></figure></div></div><div class=\"tut\"><h3>Stap 3 · Invloed</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Bovenaan staat de <b>cirkel van invloed</b>: binnenin <b>Controle</b> (je eigen handelen, beslissingen en gedrag), daaromheen <b>Invloed</b> en buiten <b>Negatieve gedachte</b> (wat jou beïnvloedt maar waar je geen invloed op hebt).</li><li>Schrijf bij <b>Waar maak je je zorgen om?</b> elke zorg op een eigen regel.</li><li>Elke zorg krijgt een nummer. Tik per zorg op <b>Controle</b>, <b>Invloed</b> of <b>Negatieve gedachte</b>; het nummer verschijnt in de cirkel.</li><li>Beantwoord daarna welke acties je kunt nemen en of je iets uit de buitenste ring naar controle of invloed kunt verplaatsen.</li></ol></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Cirkel van invloed</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Zorgen plaatsen</figcaption></figure></div></div><div class=\"tut\"><h3>Stap 4 · Toekomst</h3><ol class=\"steps\"><li>Beantwoord de zes vragen: welke vergelijkbare situaties zie je aankomen, wat pas je dan toe, welk gedrag ga je proberen, hoe maak je dat meetbaar, heb je hulp nodig en wanneer probeer je het uit?</li><li>Met <b>Gebruik als SMART-leervraag</b> stuur je het gedrag dat je gaat proberen direct door naar je SMART-leervraag (<a class=\"ho-go\" data-step=\"7\">hoofdstuk 5</a>).</li><li>Je kunt meerdere reflecties maken; ze staan als tabbladen bovenaan. Met <b>Exporteren</b> sla je een reflectie met alle vier de stappen op als tekstbestand.</li></ol><div class=\"call tip\"><b>Tip</b> Onder de reflectie zit het inklapbare blok <b>Emoties over al je reflecties</b>: welke emoties (Angst, Verdriet, Woede, Vreugde) vaak terugkomen, welke woorden je het meest koos en hoe sterk je gevoel per reflectie was.</div><div class=\"call info\"><b>Goed om te weten</b> Reflecties uit een eerdere versie blijven bewaard: je oude <i>Inzichten</i> staan nu bij <i>Wat zou je toe kunnen passen</i>, en je <i>Leervraag</i> en <i>Actieplan</i> bij <i>Wat voor gedrag ga je proberen</i>.</div></div><section class=\"sec\" id=\"A9\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Hoofdstuk 7 · Procesreflectie (Korthagen)</h2><button type=\"button\" class=\"ho-open\" data-step=\"9\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Reflecteer met de vijf fasen van de ALACT-cirkel van Korthagen: Actie, Terugblik, Bewustwording, Alternatieven en Uitproberen.</p><div class=\"tut\"><h3>Door de ALACT-cirkel</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Tik op een fase in de <b>cirkel</b> om ernaartoe te gaan. De actieve fase is goud; afgeronde fasen krijgen een vinkje.</li><li>Bij <b>Terugblik</b> beantwoord je acht korte vragen: wat wilde, dacht, voelde en deed ik, en wat wilde, dacht, voelde en deed de ander? De app maakt er één terugblik van.</li><li>Werk de fasen af met <b>Volgende fase</b>.</li><li>Klaar met <b>Uitproberen</b>? Tik op <b>Nieuwe ronde</b>. Je nieuwe ronde begint automatisch met je voornemen als actie: zo maak je de cirkel echt rond.</li></ol></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>ALACT-cirkel</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>De acht vragen</figcaption></figure></div></div><section class=\"sec\" id=\"A10\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Hoofdstuk 8 · Datum-Tijd-Feit Logboek</h2><button type=\"button\" class=\"ho-open\" data-step=\"11\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Leg concrete situaties vast met datum, tijd en feiten, en koppel ze aan de 4 V's. Dit is je bewijs bij je beoordeling.</p><div class=\"tut row\"><div class=\"txt\"><h3>Een feit vastleggen</h3><ol class=\"steps\"><li>Tik op <b>+ Nieuw feit</b>. Datum en tijd staan al ingevuld.</li><li>Beschrijf <b>feitelijk</b> wat er gebeurde: wie, wat, waar. Schrijf je een oordeel (zoals <i>lui</i> of <i>altijd</i>), dan waarschuwt de app: <i>klinkt als een interpretatie</i>.</li><li>Kies bij welke <b>V</b> dit feit hoort en vul eventueel in waarom het belangrijk is.</li><li>Geef aan of het feit <b>Positief</b> of <b>Negatief</b> was. Een positief feit krijgt een groene rand, een negatief feit een rode rand.</li><li>Koppel het feit eventueel aan een <b>sterkte</b> (S, groen) of <b>valkuil</b> (V, rood) uit je SWOT. Terwijl je typt, stelt de app passende sterktes of valkuilen voor (stippelrand).</li><li>Tik op <b>Opslaan</b>. Het feit verschijnt in de weektijdlijn.</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Waarschuwing bij een interpretatie</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Je logboek gebruiken</h3><ol class=\"steps\"><li>Bovenaan zie je bij <b>Bewijs per V</b> hoeveel feiten je per V hebt. Een lege balk laat zien waar je nog bewijs mist.</li><li>Filter met de knoppen <b>Alle / Verbondenheid / Veiligheid / …</b>.</li><li>Tik bij een feit op <b>Maak 5G-T</b> om er direct een reflectie van te maken.</li><li>Tik bij een opgeslagen feit op <b>Positief</b> of <b>Negatief</b> om de markering te wijzigen; nog eens tikken haalt hem weg.</li><li>Met <b>Exporteer</b> sla je je hele logboek op.</li></ol><div class=\"call tip\"><b>Tip</b> Schrijf een feit zo snel mogelijk op, liefst dezelfde dag. De zwevende knop <b>+ Nieuw feit</b> staat altijd rechtsonder in dit hoofdstuk.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Weektijdlijn met groene en rode rand</figcaption></figure></div></div><div class=\"tut\"><h3>Patronen in je gedrag zien</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Een feit dat je al hebt opgeslagen koppel je achteraf met <b>Sterkte/valkuil</b> onder dat feit.</li><li>Bovenaan verschijnen <b>signalen</b>, bijvoorbeeld <i>Valkuil \"Drammerigheid\" kwam 4× voor in de laatste 2 weken</i> of <i>Valkuilgedrag vooral op maandagochtend</i>.</li><li><b>Patroonkaart</b>: per sterkte en valkuil hoe vaak die voorkwam, per week (deze week links). Een pijltje laat zien of het de laatste weken vaker of minder vaak gebeurt.</li><li><b>Wanneer gebeurt het?</b>: weekdag tegen dagdeel (nacht, ochtend, middag, avond), apart voor valkuilen, sterktes en alle feiten.</li><li><b>4 V's × sterktes en valkuilen</b>: bij welke V je sterktes zich laten zien en waar je valkuilen schuren.</li><li>Elk blok kun je in- en uitklappen; de app onthoudt wat je open hebt staan.</li></ol><div class=\"call tip\"><b>Tip</b> Een valkuil die steeds op hetzelfde moment terugkomt, is een goed startpunt voor je SMART-leervraag of een 5G-T-reflectie.</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Koppelen met voorstel</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Signalen en patroonkaart</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Weekdag × dagdeel</figcaption></figure></div></div><div class=\"tut\"><h3>Van feit naar reflectie en leervraag</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Onder elk feit staan nu ook <b>Maak Korthagen</b> en <b>Bij mijn leervraag</b>.</li><li><b>Maak 5G-T</b> of <b>Maak Korthagen</b> start een nieuwe reflectie met dit feit al ingevuld als gebeurtenis of actie.</li><li>Bij het feit verschijnt daarna een knop naar de reflectie, en in de reflectie een knop terug naar het feit.</li><li><b>Bij mijn leervraag</b> zet het feit bij het bewijs van je SMART-leervraag (<a class=\"ho-go\" data-step=\"7\">hoofdstuk 5</a>).</li></ol></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Nieuwe knoppen bij een feit</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Korthagen vanuit een feit</figcaption></figure></div></div><section class=\"sec\" id=\"A11\"><div class=\"kicker\">Deel A · Reflectieboekje · Verdieping</div><h2>Hoofdstuk 9 · Zelfbeoordelingsformulier KMA</h2><button type=\"button\" class=\"ho-open\" data-step=\"5\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Het officiële cadetbeoordelingsformulier, ingevuld als zelfbeoordeling op niveau 1 en 2 van elke V.</p><div class=\"tut row\"><div class=\"txt\"><h3>Het formulier invullen</h3><ol class=\"steps\"><li>Tik op <b>Zelfbeoordelingsformulier</b> (of <a class=\"ho-go\" data-menu=\"Beoordelingsformulier\"><b>⋮ → Beoordelingsformulier</b></a>).</li><li>Vul je gegevens in en geef per V een score voor niveau 1 en niveau 2: <b>0</b> = onvoldoende, <b>1</b> = voldoende (de norm), <b>2</b> = goed. Licht je score toe met een voorbeeld.</li><li>Kies je eindoordeel en sla het formulier op.</li><li>In het hoofdstuk zie je daarna een overzicht in kleur en een meter met je totaalscore (maximaal 16), plus hoeveel DTF-bewijs je per V hebt.</li><li>Met <b>Bewerken</b> pas je het formulier aan; met <b>Exporteer (.txt)</b> sla je het op als tekstbestand.</li></ol><div class=\"call info\"><b>Goed om te weten</b> Je toelichting per V en je motivatie komen bij je teamleider als <b>Zienswijze cadet</b> op het officiële formulier (per V en bij het totaaloordeel). Schrijf ze dus zo dat je teamleider ze zo kan overnemen.</div><div class=\"call tip\"><b>Tip</b> De vier V's hebben in beide apps dezelfde pictogrammen als op het officiële formulier: handdruk (Verbondenheid), waarschuwingsdriehoek (Veiligheid), handen met hart (Vertrouwen) en groep (Verantwoordelijkheid).</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Overzicht en totaalscore</figcaption></figure></div></div><section class=\"sec\" id=\"A12\"><div class=\"kicker\">Deel A · Reflectieboekje · Verdieping</div><h2>Hoofdstuk 10 · Voorbereiding Cadetbeoordeling</h2><button type=\"button\" class=\"ho-open\" data-step=\"13\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Bereid je beoordelingsgesprek met je teamleider voor met het bewijs dat je hebt verzameld.</p><div class=\"tut\"><h3>Je gesprek voorbereiden</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Bij <b>Bewijs voor je gesprek</b> staan je DTF-feiten en reflecties. Vink aan wat je wilt bespreken.</li><li>Tik op <b>Zet in mijn antwoord</b>: de gekozen punten komen in je antwoord op de gespreksvraag.</li><li>Tik op <b>Gesprekssamenvatting</b> voor één overzichtspagina met je leerpunten, bewijs, SMART-leervraag, 4V-scores en persoonlijkheidsprofiel. Je fitheid en stressscore staan er niet in: dat hoofdstuk is altijd privé.</li><li>Tik op <b>PDF / afdrukken</b> om de samenvatting mee te nemen naar het gesprek. Onderaan is ruimte voor afspraken met je teamleider.</li></ol></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Bewijs kiezen</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Gesprekssamenvatting</figcaption></figure></div></div><section class=\"sec\" id=\"A13\"><div class=\"kicker\">Deel A · Reflectieboekje · Verdieping</div><h2>Hoofdstuk 11 · Probleem- en Behoefteanalyse</h2><button type=\"button\" class=\"ho-open\" data-step=\"10\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Analyseer een probleem systematisch met de vijf fasen van de regulatieve cyclus: Probleemstelling, Diagnostiek, Planvorming, Ingreep en Evaluatie.</p><div class=\"tut\"><h3>Een analyse doorlopen</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Bovenaan zie je de fasen 1 tot 5. Je ziet steeds de vragen van één fase; tik op een nummer om van fase te wisselen.</li><li>In de fase <b>Diagnostiek</b> zie je de balans tussen <b>draagkracht</b> (hulpbronnen, competenties) en <b>draaglast</b> (stressoren, verwachtingen). Schuif beide om te zien hoe het nu in balans is.</li><li>Met <b>+ Nieuwe analyse</b> maak je een tweede analyse voor een ander probleem. Elke analyse heeft een eigen naam.</li></ol></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Fasen</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Draagkracht en draaglast</figcaption></figure></div></div><section class=\"sec\" id=\"A14\"><div class=\"kicker\">Deel A · Reflectieboekje · Verdieping</div><h2>Hoofdstuk 12 · Fitheid &amp; stress</h2><button type=\"button\" class=\"ho-open\" data-step=\"14\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Een goede officier zorgt ook voor zichzelf. Houd je slaap, fysieke belasting en mentale druk bij en doe elke maand de stresscheck en de welzijnscheck. Dit hoofdstuk is altijd <b>privé</b>.</p><div class=\"tut\"><h3>De stresscheck invullen (PSS-10)</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Tik bij <b>Stresscheck (PSS-10)</b> op <b>Vul de PSS-10 in</b>.</li><li>Beantwoord de 10 vragen over <b>de afgelopen maand</b>. Tik per vraag op 0 (nooit) tot en met 4 (zeer vaak). Een beantwoorde vraag krijgt een gouden rand.</li><li>Tik onderaan op <b>Score berekenen en opslaan</b>. Ben je een vraag vergeten, dan springt de app naar die vraag.</li><li>Vul de check bijvoorbeeld één keer per maand in. Met <b>Opnieuw invullen</b> voeg je een nieuwe meting toe. Met het prullenbakje verwijder je er een.</li></ol><div class=\"call info\"><b>Goed om te weten</b> Vraag 4, 5, 7 en 8 zijn positief gesteld. Daar telt de app de score andersom (0 wordt 4, 1 wordt 3, enzovoort). Zo betekent een hogere totaalscore altijd meer ervaren stress.</div><div class=\"call info\"><b>Goed om te weten</b> Tot versie 4.7.0 had de stresscheck 14 vragen (de PSS-14). De PSS-10 bestaat uit 10 van die 14 vragen. Je eerdere metingen zijn daarom omgerekend met dezelfde antwoorden, en je grafiek loopt gewoon door.</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption><a class=\"ho-go\" data-step=\"14\">Hoofdstuk 12</a>, privé</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>De 10 vragen</figcaption></figure></div></div><div class=\"tut\"><h3>Je uitslag lezen</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>De meter toont je totaalscore van 0 tot 40, met een indeling als hulpmiddel: tot en met 12 <b>laag</b>, 13 tot en met 21 <b>gemiddeld</b>, 22 tot en met 29 <b>verhoogd</b> en vanaf 30 <b>hoog</b>. De PSS-10 heeft geen officiële grenzen; de indeling volgt cijfers van jonge volwassenen. Onder de meter zie je hoeveel je score is veranderd sinds je vorige meting, en of dat een <b>betrouwbare verandering</b> is (8 punten of meer) of binnen de meetfout valt.</li><li>De twee balken zijn de twee kanten die in onderzoek steeds terugkomen: <b>ervaren hulpeloosheid</b> en <b>te weinig grip</b>, als percentage van het maximum.</li><li>Heb je vaker ingevuld, dan zie je in de grafiek hoe je score zich ontwikkelt.</li><li>Bij een <b>hoge</b> score geeft de app advies om met iemand te praten: <b>geestelijke verzorging</b>, het <b>bedrijfsmaatschappelijk werk (BMW)</b>, je <b>teamleider</b>, een <b>senior-instructeur</b> of iemand uit je <b>steuncirkel</b> (de namen uit <a class=\"ho-go\" data-step=\"1\">hoofdstuk 1</a>). Bij een verhoogde score, of als je score 8 punten of meer is gestegen sinds je vorige meting (een betrouwbare stijging), volgt een korter advies.</li></ol><div class=\"call let\"><b>Let op</b> De PSS-10 meet hoeveel stress je hebt <i>ervaren</i>. Het is geen diagnose. Gaat het niet goed, wacht dan niet op een score maar praat met iemand. Gaat het helemaal niet meer, bel dan 113 (gratis via 0800-0113) of je huisarts. Bij direct gevaar bel je 112.</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Uitslag</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Advies bij een hoge score</figcaption></figure></div></div><div class=\"tut\"><h3>De welzijnscheck (WHO-5)</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Onder de stresscheck staat <b>Welzijnscheck (WHO-5)</b>. Tik op <b>Vul de WHO-5 in</b>.</li><li>Geef bij vijf uitspraken aan hoe je je <b>de laatste twee weken</b> voelde, van <i>Helemaal niet</i> tot <i>Constant</i>. Bijvoorbeeld: <i>Ik voelde me rustig en ontspannen</i>.</li><li>De app telt je antwoorden op en vermenigvuldigt met 4: een score van 0 tot 100. Hoe hoger, hoe beter het met je gaat.</li><li>Bij een score van 50 of lager geeft de app het advies om met iemand te praten. Blijft het zo, ga dan ook langs je huisarts.</li><li>Samen met de stresscheck zie je twee kanten: hoeveel druk je ervaart en hoe het met je gaat.</li></ol><div class=\"call info\"><b>Goed om te weten</b> De WHO-5 is een korte, veel gebruikte vragenlijst van de Wereldgezondheidsorganisatie. De app gebruikt de officiële Nederlandse vertaling.</div><div class=\"call privacy\"><b>Privacy</b> De welzijnscheck is, net als de rest van <a class=\"ho-go\" data-step=\"14\">hoofdstuk 12</a>, altijd privé en gaat nooit mee met je dossier.</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Welzijnscheck</figcaption></figure></div></div><div class=\"tut\"><h3>Je fitheid bijhouden</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Kies bij <b>Fitheidslogboek</b> de datum en schuif <b>Slaap en rust</b>, <b>Fysieke belasting</b> en <b>Mentale druk</b> (1 tot 10). Voeg eventueel een notitie toe.</li><li>Tik op <b>Meting opslaan</b>. De grafiek toont je laatste metingen.</li><li>Heb je drie keer op rij slecht geslapen of drie keer op rij hoge mentale druk, dan verschijnt een melding met het advies om met je teamleider of een buddy te praten.</li><li><b>Week in samenhang</b> zet per week je slaap, mentale druk, je DTF-feiten (sterktes en valkuilen) en de sterkte van je emoties uit 5G-T naast elkaar. Legde je in drukke weken meer valkuilgedrag vast, dan meldt de app dat.</li></ol></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Fitheidslogboek</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Week in samenhang</figcaption></figure></div></div><div class=\"tut\"><h3>Het groepsgesprek: de gespreksgids</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Open onderaan <b>Gespreksgids voor je groepje</b>. Die is bedoeld voor een gesprek met 6 tot 8 personen.</li><li>Bespreek de zes vragen: <b>de spiegel</b>, <b>het masker</b>, <b>signalen</b>, <b>grenzen</b>, <b>veiligheid</b> en <b>steun</b>.</li><li>Doe daarna de vervolgopdracht <b>de gemene deler</b>: tel de totaalscores op en bereken het gemiddelde, zoek de gedeelde stressbronnen, maak samen één kernzin en spreek één manier af om elkaar te steunen.</li><li>Typ de totaalscores van het groepje in het vak en tik op <b>Gemiddelde</b>. Die scores blijven op je telefoon en worden nooit gedeeld.</li><li>Sluit af met de <b>bonusvraag</b>: welke vraag zou je graag eens oprecht gesteld krijgen?</li></ol><div class=\"call privacy\"><b>Privacy</b> Iedereen bepaalt zelf of hij zijn score noemt. Je hoeft je score niet te delen om mee te doen.</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Gespreksgids</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Gemene deler</figcaption></figure></div></div><div class=\"tut\"><h3>Altijd privé</h3><ol class=\"steps\"><li>Dit hoofdstuk is van jou. Onder de hoofdstuktitel staat <b>Altijd privé</b>; er is geen schakelaar om het te delen.</li><li>Je fitheidslogboek, je stressscores en je antwoorden blijven op je telefoon. Ze gaan nooit mee als je je dossier deelt, ook niet via de gedeelde map of een QR-code.</li><li>Wil je er toch met je teamleider over praten? Vertel het hem zelf, of laat het scherm zien. Jij bepaalt wat je vertelt.</li></ol><div class=\"call privacy\"><b>Privacy</b> Ook de groepsscores uit de gespreksgids worden nooit gedeeld.</div></div><section class=\"sec\" id=\"A15\"><div class=\"kicker\">Deel A · Reflectieboekje · Verdieping</div><h2>Hoofdstuk 13 · Curriculum vitae</h2><button type=\"button\" class=\"ho-open\" data-step=\"17\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Vul een net cv in. Het komt als eerste onderdeel in je portfolio.</p><div class=\"tut\"><h3>Je cv invullen</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Je naam, krijgsmachtdeel en dienstvak neemt de app over uit <a class=\"ho-go\" data-step=\"0\">hoofdstuk 0</a>.</li><li>Vul je <b>persoonlijke gegevens</b> in (geboortedatum, woonplaats, e-mail, telefoon, rijbewijs) en schrijf een kort <b>profiel</b>: twee tot vier zinnen over wie je bent en wat je drijft.</li><li>Voeg met <b>+ Toevoegen</b> regels toe bij <b>Militaire loopbaan en werkervaring</b>, <b>Opleidingen</b>, <b>Cursussen en certificaten</b>, <b>Talen</b> (met niveau) en <b>Nevenactiviteiten en sport</b>.</li><li>Zet bij <b>Vaardigheden</b> je vaardigheden achter elkaar, gescheiden door komma's.</li><li>Alles wordt automatisch opgeslagen. Met het prullenbakje verwijder je een regel.</li></ol><div class=\"call privacy\"><b>Privacy</b> Je cv staat standaard op <b>privé</b>. Zet de schakelaar aan als je wilt dat je teamleider het kan lezen.</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Gegevens en profiel</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Opleidingen en cursussen</figcaption></figure></div></div><section class=\"sec\" id=\"A16\"><div class=\"kicker\">Deel A · Reflectieboekje · Naslag en overzicht</div><h2>Hoofdstuk 14 · Toetsing en examinering DKOO</h2><button type=\"button\" class=\"ho-open\" data-step=\"15\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Hier zie je waarop je in de DKOO getoetst wordt, per blok: AMO en themablok 1, 2 en 3. Je houdt zelf bij wat je hebt behaald.</p><div class=\"tut\"><h3>Je toetsen bijhouden</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Bovenaan zie je hoeveel <b>summatieve</b> toetsen voldoende zijn en hoeveel <b>formatieve</b> toetsen zijn afgerond.</li><li>Per blok staan de toetsen onder elkaar. Een rood label <b>Summatief</b> betekent dat de toets meetelt voor je beoordeling. Een blauw label <b>Formatief</b> is een toets om van te leren.</li><li>Bij een summatieve toets tik je op <b>Voldoende</b>, <b>Onvoldoende</b> of <b>Nog niet</b>. Bij een formatieve toets zet je een vinkje bij <b>Afgerond</b>.</li><li>Met de knoppen bovenaan filter je op <b>Summatief</b>, <b>Formatief</b>, <b>Nog open</b> of <b>Onvoldoende</b>.</li></ol><div class=\"call info\"><b>Goed om te weten</b> Heeft je teamleider een uitslag vastgelegd, dan zie je die onder de toets, bijvoorbeeld <i>Teamleider: voldoende (21 okt)</i>. Die uitslag komt mee met de feedback van je teamleider.</div><div class=\"call privacy\"><b>Privacy</b> Wat je zelf invult, gaat mee als je je dossier deelt. Zo ziet je teamleider waar jullie van elkaar verschillen. Je kunt dit hoofdstuk ook privé zetten.</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Summatieve toetsen</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Formatief: afgerond</figcaption></figure></div></div><section class=\"sec\" id=\"A17\"><div class=\"kicker\">Deel A · Reflectieboekje · Naslag en overzicht</div><h2>Hoofdstuk 15 · Begrippenlijst &amp; Vakjargon</h2><button type=\"button\" class=\"ho-open\" data-step=\"12\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Militaire begrippen, afkortingen en vakjargon met uitleg.</p><div class=\"tut\"><h3>Zoeken en leren</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>In de weergave <b>Lijst</b> zoek je met het zoekveld, filter je op categorie (Beoordeling, Ontwikkeling, Organisatie, …) of spring je met de letters naar een beginletter.</li><li>Kies <b>Flitskaarten</b> om begrippen te leren: tik op de kaart om hem om te draaien.</li><li>Tik op <b>Ken ik</b> of <b>Nog niet</b>. De app houdt bij hoeveel begrippen je al kent; de begrippen die je nog niet kent komen terug.</li></ol></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Lijst</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Flitskaarten</figcaption></figure></div></div><section class=\"sec\" id=\"A18\"><div class=\"kicker\">Deel A · Reflectieboekje · Naslag en overzicht</div><h2>Hoofdstuk 16 · Mijn groei &amp; ontwikkeling</h2><button type=\"button\" class=\"ho-open\" data-step=\"16\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Alles wat je in dit boekje doet en wat je teamleider terugkoppelt, komt hier samen op één tijdlijn. Zo zie je waar je groeit en waar je verder wilt.</p><div class=\"tut\"><h3>Je groei in één oogopslag</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Bovenaan staan vier tegels: hoeveel <b>beoordelingen</b> er zijn (van jezelf en van je teamleider), hoeveel <b>reflecties</b> je maakte (met hoeveel je geloof in een negatieve gedachte daalde), je <b>DTF-feiten</b> (positief en negatief) en je <b>gelukte check-ins</b> van je SMART-leervraag.</li><li>Bij <b>Beoordelingen over tijd</b> zie je per V een kleine grafiek: je eigen zelfbeoordeling naast de beoordeling van je teamleider. Een pijltje <b>gegroeid</b> laat zien dat je score omhoog ging.</li><li><b>DTF-feiten per maand</b> laat met groene en rode staafjes zien hoeveel positieve en negatieve feiten je per maand vastlegde.</li></ol></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Tegels</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Per V over tijd</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Je tijdlijn en je eigen woorden</h3><ol class=\"steps\"><li>Bij <b>Jouw groei op een tijdlijn</b> staan per maand je zelfbeoordelingen, de beoordelingen van je teamleider, je 5G-T- en Korthagen-reflecties en je check-ins.</li><li>Bij een 5G-T-reflectie zie je hoeveel procentpunt je geloof in je belangrijkste gedachte daalde.</li><li>Beantwoord daaronder de drie <b>groeivragen</b>: waar je het meest in gegroeid bent, wat je daarbij het meest hielp en waar je verder in wilt groeien.</li></ol><div class=\"call info\"><b>Goed om te weten</b> Elke keer dat je je zelfbeoordeling of je 4V-scores opslaat, bewaart de app een meetmoment. Hoe langer je het boekje gebruikt, hoe meer punten de grafieken krijgen.</div><div class=\"call privacy\"><b>Privacy</b> Deel je dit hoofdstuk, dan ziet je teamleider je groei en je antwoorden ook.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Tijdlijn</figcaption></figure></div></div><section class=\"sec\" id=\"A19\"><div class=\"kicker\">Deel A · Reflectieboekje · Naslag en overzicht</div><h2>Hoofdstuk 17 · Roos van Leary</h2><button type=\"button\" class=\"ho-open\" data-step=\"18\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Welk gedrag laat je zien in een groep, en zien anderen dat ook zo? Je DTF-feiten en de feedback van anderen op de Roos van Leary, met uitleg.</p><div class=\"tut row\"><div class=\"txt\"><h3>Gedrag kiezen op de roos</h3><ol class=\"steps\"><li>Open bij een nieuw DTF-feit <b>Roos van Leary (optioneel)</b>. Tik op de plek die past bij het gedrag dat je liet zien: de binnenring is <i>een beetje</i>, de buitenring <i>duidelijk</i>. Nog eens tikken of <b>Wissen</b> haalt de keuze weg.</li><li>Bij een feit dat al in je logboek staat, tik je op <b>Roos</b> om de plek te kiezen of te wijzigen.</li><li>Geef je feedback aan een medecadet, dan kun je ook daar de plek op de roos kiezen. Je teamleider kan het bij een DTF-notitie doen.</li><li>In het DTF-logboek filter je bij <b>Meer filters</b> op een soort gedrag.</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Kiezen bij een DTF-feit</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Je roos bekijken</h3><ol class=\"steps\"><li>Open dit hoofdstuk (Naslag en overzicht). Vanaf vijf feiten met een plek op de roos zie je hoe je gedrag verdeeld is: goud is wat jij koos, de blauwe lijn is wat medecadetten en je teamleider kozen.</li><li>Het stipje is je gemiddelde plek. Daaronder zie je die ook als twee balkjes: onder of boven, tegen of samen.</li><li>Bij <b>Per soort gedrag</b> zie je per sector wat het betekent, welk gedrag het vaak bij anderen uitlokt en welke van je feiten erbij horen.</li><li>Bij <b>Naast je persoonlijkheidstest</b> staan je uitkomsten op extraversie en verdraagzaamheid. Leg ze naast de roos, maar trek geen conclusies uit één van beide.</li><li>Onderaan staat de uitleg: hoe de roos werkt en hoe je hem gebruikt in het gesprek met je teamleider.</li></ol><div class=\"call info\"><b>Goed om te weten</b> Geen enkel gedrag op de roos is goed of fout. Het gaat erom dat je ziet wat je doet, wat dat bij anderen oproept en of je bewust kunt kiezen.</div><div class=\"call privacy\"><b>Privacy</b> De plek op de roos staat bij je DTF-feiten. Deel je het DTF-logboek met je teamleider, dan ziet hij die ook.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Jouw roos</figcaption></figure></div></div><section class=\"sec\" id=\"A20\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Je portfolio als PDF</h2><p class=\"lead\">Maak van al je producten één mooi opgemaakt portfolio: een voorblad, een inhoudsopgave en per onderdeel een eigen pagina.</p><div class=\"tut row\"><div class=\"txt\"><h3>Een portfolio maken</h3><ol class=\"steps\"><li>Tik op <a class=\"ho-go\" data-menu=\"Portfolio (PDF)\"><b>⋮ → Portfolio (PDF)</b></a> of op <a class=\"ho-go\" data-share=\"Portfolio (PDF)\"><b>Delen → Portfolio (PDF)</b></a>.</li><li>Je ziet een voorbeeld van je portfolio. Kies bij <b>Kies wat erin komt</b> welke onderdelen je meeneemt. Hoofdstukken waar je nog niets invulde, staan uit.</li><li>Je <b>cv</b> komt als eerste onderdeel, daarna je hoofdstukken met je levenslijn, grafieken, reflecties, DTF-logboek en je groei.</li><li>Tik op <b>Download als PDF</b> en kies bij het afdrukken <b>Opslaan als PDF</b> als printer.</li></ol><div class=\"call tip\"><b>Tip</b> Gebruik het portfolio bij je beoordelingsgesprek, een sollicitatie of een overplaatsing. Kies alleen de onderdelen die je wilt laten zien.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Onderdelen kiezen</figcaption></figure></div></div><div class=\"tut\"><h3>Voorbeeld van een portfolio</h3><p>Voorblad, cv, levenslijn en groei uit het portfolio van de fictieve demo-cadet Daan Verhoeven.</p><div class=\"phones\"><figure class=\"phone\" style=\"width:23%\"><img src=\"data:image/webp;base64,\" loading=\"lazy\" style=\"border-radius:4px;border:1px solid #ccc\"/><figcaption>Voorblad</figcaption></figure><figure class=\"phone\" style=\"width:23%\"><img src=\"data:image/webp;base64,\" loading=\"lazy\" style=\"border-radius:4px;border:1px solid #ccc\"/><figcaption>Curriculum vitae</figcaption></figure><figure class=\"phone\" style=\"width:23%\"><img src=\"data:image/webp;base64,\" loading=\"lazy\" style=\"border-radius:4px;border:1px solid #ccc\"/><figcaption>Levenslijn</figcaption></figure><figure class=\"phone\" style=\"width:23%\"><img src=\"data:image/webp;base64,\" loading=\"lazy\" style=\"border-radius:4px;border:1px solid #ccc\"/><figcaption>Mijn groei</figcaption></figure></div></div><div class=\"tut\"><h3>Het portfolio volgt je rode draad (sinds 4.30)</h3><ol class=\"steps\"><li>Het portfolio staat in de volgorde van je rode draad: <i>Jezelf leren kennen</i>, <i>Leervraag</i>, <i>Doen en vastleggen</i>, <i>Reflecteren</i> en <i>Feedback en beoordeling</i>, daarna verdieping en naslag.</li><li>Nieuw: je <b>metingen</b> van de persoonlijkheidstest (kort of lang), je <b>als-dan-plannen</b> met check-ins, het <b>gereedschap</b> dat je gebruikte, de SWOT met bewijs en een <b>bijlage met bronnen</b>.</li><li>Hoofdstukken die privé zijn, staan standaard uit. Je eerdere keuzes blijven bewaard.</li></ol></div><section class=\"sec\" id=\"A21\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Je dossier delen met je teamleider</h2><p class=\"lead\">Alles wat je deelt, loopt via de knop <a class=\"ho-go\" data-click=\"#kma-share-btn\"><b>Delen</b></a> bovenaan. Voordat er iets wordt verstuurd, zie je altijd eerst wat je deelt.</p><div class=\"tut row\"><div class=\"txt\"><h3>Wat deel je?</h3><ol class=\"steps\"><li>Bovenaan het menu <a class=\"ho-go\" data-click=\"#kma-share-btn\"><b>Delen</b></a> staat hoeveel hoofdstukken je deelt, welke privé blijven, wanneer je voor het laatst deelde, wanneer je teamleider je dossier ontving (<b>ontvangen</b>) en of de deelmap gekoppeld is.</li><li>De app zet <b>Aanbevolen</b> bij de beste manier: een <b>QR-code</b> voor een snel profiel, of een <b>bestand</b> (Quick Share) zodra je DTF-feiten of reflecties hebt.</li><li>Lees je per ongeluk je eigen gedeelde bestand in als back-up, dan neemt de app alleen de gedeelde onderdelen over; je privé-hoofdstukken blijven staan.</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Wat je deelt</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Het Delen-menu</h3><ol class=\"steps\"><li><b>QR-code tonen</b>: je teamleider scant de code met het CadetVolgSysteem. Snel, zonder internet of Bluetooth.</li><li><b>Via Quick Share of Bluetooth</b>: stuurt je volledige dossier als bestand. Heb je een groepscode ingevuld, dan is het bestand versleuteld (zie pagina <a class=\"ref\" href=\"#A22\">A22</a>). Kies in het deelmenu van Android <b>Quick Share</b>: dat is vele malen sneller dan Bluetooth.</li><li><b>Portfolio (PDF)</b>: al je producten in een opgemaakt portfolio (zie pagina <a class=\"ref\" href=\"#A20\">A20</a>).</li><li><b>PDF / afdrukken</b>: een opgemaakt verslag van al je antwoorden.</li><li>Een back-up voor jezelf staat niet bij Delen maar in het menu: <a class=\"ho-go\" data-menu=\"Back-up maken\"><b>⋮ → Back-up maken</b></a> (zie pagina <a class=\"ref\" href=\"#A23\">A23</a>).</li></ol><div class=\"call info\"><b>Goed om te weten</b> Een volledig dossier wordt ingepakt verstuurd als <b>.kma</b>-bestand, meestal 5 tot 10 keer kleiner dan gewone tekst. Het CadetVolgSysteem pakt het vanzelf uit. Jij en je teamleider hebben daarvoor wel allebei de nieuwste versie van de app nodig.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Delen</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Kiezen wat je deelt</h3><ol class=\"steps\"><li>Na het kiezen van QR-code of Quick Share verschijnt <b>Wat deel je met je teamleider?</b></li><li>Per hoofdstuk zie je een schakelaar. Zet uit wat privé moet blijven; de app onthoudt je keuze.</li><li>Tik op <a class=\"ho-go\" data-click=\"#kma-share-btn\"><b>Delen</b></a> om door te gaan.</li></ol><div class=\"call privacy\"><b>Privacy</b> Je profiel (naam, OPCO, Peoplesoft-nummer) wordt altijd gedeeld, zodat je teamleider weet van wie het dossier is.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Wat deel je?</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>QR-code: snel profiel</h3><ol class=\"steps\"><li>Houd je telefoon met de QR-code voor de camera van je teamleider.</li><li>De QR-code bevat een <b>snel profiel</b>: je naam, je persoonlijkheidsscores en de scores van je zelfbeoordeling. Een QR-code is te klein voor al je teksten en je foto.</li><li>Wil je je teamleider je <b>volledige dossier</b> geven (alle antwoorden, reflecties, DTF-logboek, foto)? Gebruik dan <b>Via Quick Share of Bluetooth</b>.</li></ol><div class=\"call info\"><b>Goed om te weten</b> Scant je teamleider een QR-code van een cadet die al in het volgsysteem staat, dan worden alleen de nieuwe scores bijgewerkt. Eerder ontvangen teksten blijven staan.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>QR-code</figcaption></figure></div></div><section class=\"sec\" id=\"A22\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Versleuteld delen en de deelmap</h2><p class=\"lead\">Met een <b>groepscode</b> van je teamleider deel je je dossier versleuteld. Met de <b>deelmap</b> gaat dat zelfs vanzelf: je dossier gaat naar je teamleider en zijn feedback komt automatisch terug.</p><div class=\"tut\"><h3>Koppelen met je teamleider (QR-code)</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Je teamleider laat je de QR-code van je groep zien.</li><li>Open <a class=\"ho-go\" data-menu=\"Koppelen met je teamleider\"><b>⋮ → Koppelen met je teamleider</b></a> en tik op <b>Scan QR-code</b>. Geef de app de eerste keer toegang tot de camera.</li><li>Richt de camera op de QR-code. Je ziet <b>Gekoppeld met groep ...</b> met de naam van je teamleider. Je groepscode staat nu goed.</li><li>In de app op je telefoon of pc tik je daarna op <b>Deelmap kiezen</b>. Je ziet waar je teamleider de deelmap heeft gezet, bijvoorbeeld in SharePoint. Kies die map; je telefoon vraagt daar één keer toestemming voor.</li><li>Lukt scannen niet? Tik op <b>Code intypen</b> en typ de groepscode over.</li></ol><div class=\"call privacy\"><b>Privacy</b> De koppeling en de groepscode blijven op je telefoon. Ze gaan nooit mee als je je dossier deelt.</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Scannen</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Gekoppeld</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>De groepscode invullen</h3><ol class=\"steps\"><li>Je teamleider geeft je groep een groepscode, bijvoorbeeld <i>K7QM-4XTR-9PLA</i>.</li><li>Open <a class=\"ho-go\" data-menu=\"Versleuteld delen\"><b>⋮ → Versleuteld delen</b></a>, typ de code en tik op <b>Opslaan</b>. Makkelijker is scannen: zie hierboven.</li><li>Vanaf nu is alles wat je via Quick Share of Bluetooth deelt <b>versleuteld</b>. Alleen het CadetVolgSysteem met dezelfde code kan het openen. In het menu Delen staat <i>Versleuteld met groepscode</i>.</li><li>Feedback die je teamleider versleuteld terugstuurt, opent je app met dezelfde code.</li></ol><div class=\"call let\"><b>Let op</b> Deel de groepscode niet buiten je groep. Krijg je een nieuwe code, vul die dan opnieuw in; met <b>Uitzetten</b> deel je weer onversleuteld.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Groepscode invullen</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>De deelmap koppelen</h3><ol class=\"steps\"><li>Je teamleider maakt een gedeelde map, bijvoorbeeld in OneDrive of SharePoint, en deelt die met je groep.</li><li>Vul eerst je <b>groepscode</b> in (zie hierboven) en zorg dat je naam en <b>Peoplesoft-nummer</b> in <a class=\"ho-go\" data-step=\"0\">hoofdstuk 0</a> staan.</li><li>Open <a class=\"ho-go\" data-menu=\"Deelmap\"><b>⋮ → Deelmap</b></a> en tik op <b>Map kiezen</b>. Kies de gedeelde map van je teamleider.</li><li>De app controleert of de map bij jouw groepscode hoort en maakt daarin <b>een eigen map voor jou</b>, met een code die uit je Peoplesoft-nummer wordt afgeleid.</li><li>Daarna gaat het vanzelf: wat je in gedeelde hoofdstukken verandert, staat binnen een minuut in de map. Feedback van je teamleider komt automatisch terug in je boekje.</li><li>In het scherm Deelmap zie je de map, je groep en wanneer er voor het laatst is bijgewerkt. Dat gaat vanzelf: bij openen, bij terugkomen in de app en elke minuut. Bij <i>Je dossier</i> zie je of je teamleider het heeft ontvangen en gelezen. Werkt iets niet, tik dan op <b>Deelmap controleren</b>: je ziet alleen wat er mis is en wat je moet doen. Met <b>Ontkoppelen</b> stop je.</li></ol><div class=\"call privacy\"><b>Privacy</b> Alles in de deelmap is versleuteld. Je dossier kan alleen je eigen team openen; je feedback kan alleen jouw app openen. Andere cadetten in de map kunnen jouw gegevens niet lezen. Privé-hoofdstukken worden nooit gedeeld.</div><div class=\"call info\"><b>Goed om te weten</b> Bij elk dossier dat je teamleider ontvangt, krijg je een <b>ontvangstbevestiging</b>. Die zie je in het menu Delen.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Deelmap gekoppeld</figcaption></figure></div></div><div class=\"tut\"><h3>De mappen in de deelmap (sinds 4.30)</h3><ol class=\"steps\"><li>Je dossier staat in de deelmap in een map met een <b>code</b> in plaats van je Peoplesoft-nummer. Wie de map opent, ziet dus niet meteen wiens dossier het is. De inhoud is zoals altijd versleuteld.</li><li>De overstap gaat vanzelf: na de eerste keer delen staat je dossier in de nieuwe map en ruimt het boekje je oude dossier op. Feedback in je oude map kun je nog steeds lezen.</li><li>Geef in OneDrive of SharePoint alleen je eigen peloton toegang tot de map, en de teamleider schrijfrechten. Zo kan niemand anders bestanden neerzetten.</li></ol><div class=\"call privacy\"><b>Privacy</b> De code is geen geheim: met moeite is je nummer eruit terug te rekenen. Je gegevens zelf kan alleen je teamleider openen.</div></div><section class=\"sec\" id=\"A23\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Back-up maken en terugzetten</h2><p class=\"lead\">Je antwoorden staan alleen op je eigen telefoon. Maak daarom regelmatig een back-up, zeker voor je van telefoon wisselt.</p><div class=\"tut row\"><div class=\"txt\"><h3>Back-up maken</h3><ol class=\"steps\"><li>Tik op <a class=\"ho-go\" data-menu=\"Back-up maken\"><b>⋮ → Back-up maken</b></a>.</li><li>De app vraagt om een <b>wachtwoord</b> van minstens 10 letters of cijfers. Typ het twee keer en tik op <b>Beveiligd opslaan</b>.</li><li>De app zet <b>KMA_Reflectieboekje_Backup.json</b> in <i>Downloads/KMA</i>. Zonder het wachtwoord kan niemand het bestand lezen.</li><li>Kies je <b>Zonder wachtwoord</b>, dan krijg je zoals vroeger de back-up en een tekstbestand met al je antwoorden, allebei leesbaar.</li><li>Kopieer de back-up naar een veilige plek, bijvoorbeeld je computer.</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Back-up met wachtwoord</figcaption></figure></div></div><div class=\"tut\"><h3>Back-up terugzetten</h3><ol class=\"steps\"><li>Installeer het Reflectieboekje op je nieuwe telefoon.</li><li>Open <a class=\"ho-go\" data-menu=\"Back-up terugzetten\"><b>⋮ → Back-up terugzetten</b></a> en kies het bestand <b>KMA_Reflectieboekje_Backup.json</b>. Een gedeeld <b>.kma</b>-bestand werkt ook.</li><li>Is de back-up beveiligd, dan vraagt de app om het wachtwoord.</li><li>Al je antwoorden, reflecties, je logboek en je testresultaten komen terug.</li></ol><div class=\"call let\"><b>Let op</b> Ben je het wachtwoord kwijt, dan is de back-up niet meer te openen. Ook de maker van de app kan hem niet openen. Schrijf het wachtwoord op een veilige plek op.</div><div class=\"call let\"><b>Let op</b> Een back-up <b>zonder</b> wachtwoord is leesbaar voor iedereen die het bestand heeft. Verwijder oude kopieën die je niet meer nodig hebt.</div></div><section class=\"sec\" id=\"A24\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Feedback van je teamleider ontvangen</h2><p class=\"lead\">Je teamleider of senior-instructeur kan de feedback uit het CadetVolgSysteem naar je toesturen. Je ziet die daarna bij het hoofdstuk waar hij over gaat.</p><div class=\"tut row\"><div class=\"txt\"><h3>Feedback inlezen</h3><ol class=\"steps\"><li>Gebruik je de <b>deelmap</b>, dan komt feedback vanzelf binnen en hoef je niets te doen. Anders stuurt je teamleider je een bestand <b>KMA_Feedback_…json</b>, meestal via Quick Share. Het komt in je map <i>Downloads</i>.</li><li>Open in het Reflectieboekje <a class=\"ho-go\" data-menu=\"Feedback van je teamleider\"><b>⋮ → Feedback van je teamleider → Feedback importeren</b></a> en kies het bestand.</li><li>Er opent een overzicht met de hoofdstukken waar feedback bij staat. Tik op een hoofdstuk om ernaartoe te gaan.</li><li>Kies je het bestand per ongeluk via <b>Back-up terugzetten</b>? Dan herkent de app het ook als feedback; je eigen antwoorden blijven gewoon staan.</li></ol><div class=\"call let\"><b>Let op</b> Is de feedback voor iemand met een andere naam dan in jouw Reflectieboekje, dan vraagt de app eerst of je hem toch wilt inlezen.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Overzicht na het inlezen</figcaption></figure></div></div><div class=\"tut\"><h3>Feedback lezen</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Bovenaan het hoofdstuk staat de kaart <b>Feedback van je teamleider</b>, met de naam van je teamleider en de datum.</li><li>Bij het DTF-logboek zie je de waarnemingen die je teamleider met je deelde, met wie ze vastlegde en of ze positief of negatief waren.</li><li>Bij <a class=\"ho-go\" data-step=\"10\">hoofdstuk 11</a> zie je de <b>verbeter- of ontwikkelplannen</b> die je teamleider met je opstelde.</li><li>Bij het <b>Zelfbeoordelingsformulier</b> en bij <b>Voorbereiding Cadetbeoordeling</b> zie je de cadetbeoordeling van je teamleider: de score per gedragsregel en per V, het totaaloordeel en de toelichting.</li><li>Nieuwe feedback die je nog niet bekeek, meldt de app op het startscherm.</li></ol><div class=\"call tip\"><b>Tip</b> Vergelijk de scores van je teamleider met je eigen zelfbeoordeling. Waar verschillen ze? Dat is een goed gespreksonderwerp.</div><div class=\"call privacy\"><b>Privacy</b> Ontvangen feedback staat in je back-up, maar wordt niet teruggestuurd als je je dossier deelt.</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Feedback bij SMART</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Beoordelingsformulier</figcaption></figure></div></div><div class=\"tut\"><h3>Feedback in je reflecties</h3><div class=\"row2\"><div class=\"txt\"><ol class=\"steps\"><li>Bij een 5G-T- of Korthagen-reflectie staat de kaart <b>Feedback van je teamleider</b> direct onder de titel, met <b>nieuw</b> zolang je hem nog niet las.</li><li>Je teamleider kan feedback geven <b>per stap</b>. Die zie je in de stap zelf, onder <b>Feedback op deze stap</b>.</li><li>Feedback op een reflectie die je inmiddels verwijderde, staat nog in het overzicht van het hoofdstuk.</li></ol><div class=\"call privacy\"><b>Privacy</b> Waarnemingen die instructeurs over jou vastleggen (DTF-notities) zie je alleen als de teamleider ze bewust met je deelt.</div></div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Feedback bij de reflectie</figcaption></figure><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Feedback op een stap</figcaption></figure></div></div><section class=\"sec\" id=\"A25\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>Feedback van en voor medecadetten</h2><p class=\"lead\">Sinds 4.9.0 geven cadetten elkaar feedback, in de vorm van een DTF-kaart. Je vindt alles onder <b>+ Nieuw → Feedback van en voor medecadetten</b>.</p><div class=\"tut\"><h3>Feedback geven</h3><ol class=\"steps\"><li>Tik op <b>+ Nieuw → Feedback van en voor medecadetten → Feedback geven</b>.</li><li>Kies aan wie (met de deelmap) of typ de naam van je medecadet. Vul de <b>situatie</b>, <b>datum en tijd</b> in.</li><li><b>Wat zag of hoorde je?</b> Beschrijf alleen gedrag, geen oordeel: <i>Je gaf de opdracht zonder het doel te noemen</i>, niet <i>Je bent onduidelijk</i>. Gebruik je woorden als <i>altijd</i>, <i>nooit</i> of <i>je bent …</i>, dan vraagt de app of je het anders wilt zeggen.</li><li>Vul het <b>effect</b> in, kies eventueel een van de vier V's en kies <b>Vasthouden</b> of <b>Verbeteren</b>. Sluit af met één concrete <b>tip</b>.</li><li>Tik op <b>Versturen</b>. Met de deelmap komt de kaart vanzelf bij je medecadet. Zonder deelmap laat je je medecadet de <b>QR-code</b> scannen, of deel je de kaart <b>als bestand</b>.</li></ol><div class=\"call let\"><b>Let op</b> Ongevraagd geef je hooguit <b>twee keer per week</b> feedback (maandag tot en met zondag). Op een vraag van een medecadet kan het altijd.</div><div class=\"call privacy\"><b>Privacy</b> Feedback is standaard niet anoniem: je medecadet ziet van wie de kaart komt, en de kaart is ondertekend (✓ echt van …). Kies je <i>Anoniem versturen</i>, dan ziet hij dat niet; anonieme kaarten verschijnen pas als hij er minstens drie heeft. Een kaart is versleuteld met de groepscode; via de deelmap kan alleen de ontvanger hem lezen, ook niet de andere cadetten.</div></div><div class=\"tut\"><h3>Feedback vragen aan je groep</h3><ol class=\"steps\"><li>Tik op <b>Feedback vragen</b>. Beschrijf de situatie en waarop je feedback wilt, bijvoorbeeld <i>Hoe ik opdrachten gaf</i>, en kies een einddatum.</li><li>Met de deelmap kies je <b>Hele groep</b> of <b>Een paar medecadetten</b>. Zonder deelmap laat je de QR-code scannen of deel je de vraag als bestand, bijvoorbeeld in de groepsapp.</li><li>Je medecadetten zien je vraag bij <b>Vragen van medecadetten</b> en kunnen meteen antwoorden.</li><li>Onder <b>Mijn vragen</b> zie je per vraag hoeveel antwoorden er zijn, hoe vaak <i>vasthouden</i> en <i>verbeteren</i> werd gekozen, welke V's genoemd zijn, en elke kaart apart.</li></ol><div class=\"call tip\"><b>Tip</b> Een paar mensen persoonlijk vragen levert meestal meer en betere antwoorden op dan de hele groep. Vraag bijvoorbeeld de drie mensen die het dichtst bij je stonden.</div></div><div class=\"tut\"><h3>Feedback ontvangen</h3><ol class=\"steps\"><li>Nieuwe kaarten zie je aan een rode stip op <b>+ Nieuw</b>. Ze staan onder <b>Ontvangen feedback</b>.</li><li>Kreeg je een QR-code of bestand? Tik op <b>QR-code scannen of bestand kiezen</b>.</li><li>Tik op een kaart om hem te lezen. Met <b>In mijn DTF-logboek</b> zet je hem in je logboek, met de datum, de tijd en de V. Met <b>Verwijderen</b> gooi je hem weg (je kunt dat nog even ongedaan maken).</li></ol><div class=\"call privacy\"><b>Privacy</b> Een kaart is alleen van jou. Je teamleider ziet hem pas als jij hem in je DTF-logboek zet én dat hoofdstuk deelt.</div></div><div class=\"tut row\"><div class=\"txt\"><h3>Reageren op feedback</h3><ol class=\"steps\"><li>Onder elke feedback van je teamleider staan twee knoppen: <b>Verwerkt</b> en <b>Reageren</b>.</li><li>Met <b>Verwerkt</b> laat je zien dat je er iets mee deed. Met <b>Reageren</b> schrijf je een korte reactie, bijvoorbeeld een vraag of wat je hebt aangepast. Je kunt het ongedaan maken of de reactie later wijzigen.</li><li>Je reacties gaan mee als je je dossier deelt; je teamleider ziet ze in je dossier.</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Reageren op feedback</figcaption></figure></div></div><div class=\"tut\"><h3>Gesprekken met je teamleider</h3><ol class=\"steps\"><li>Maakt je teamleider een gespreksverslag en deelt hij dat met je, dan zie je het in <a class=\"ho-go\" data-step=\"0\">hoofdstuk 0</a> onder <b>Gesprekken</b>: de datum, wat besproken is, de afspraken en het vervolggesprek.</li><li>Afspraken voor jou staan ook in de kaart <b>Vandaag</b>. Tik op <b>Gedaan</b> als je een afspraak hebt uitgevoerd.</li></ol></div><div class=\"tut\"><h3>Een kaart geven telt niet mee voor de beoordeling</h3><ol class=\"steps\"><li>Bij <b>Feedback geven</b> staat: <i>Je kaart is om van te leren. Hij telt niet mee voor de beoordeling van je medecadet.</i></li><li>Ook in het CadetVolgSysteem staan kaarten van medecadetten niet bij de waarnemingen voor het beoordelingsformulier. Ze zijn voor het gesprek.</li></ol></div><section class=\"sec\" id=\"A26\"><div class=\"kicker\">Deel A · Reflectieboekje</div><h2>De Dashboard-weergave in het Reflectieboekje</h2><p class=\"lead\">Naast de klassieke indeling heeft het boekje een Dashboard-weergave: overzichten met tegels en zes vaste knoppen onderin. Je gegevens zijn in beide weergaven hetzelfde; je kunt altijd terug.</p><div class=\"tut\"><h3>Dashboard kiezen</h3><ol class=\"steps\"><li>Open <a class=\"ho-go\" data-menu=\"Indeling: Dashboard\"><b>⋮ → Indeling: Dashboard</b></a> (in de Dashboard-weergave heet ⋮ de knop <b>Meer</b>). De app start opnieuw in de nieuwe indeling.</li><li>Terug naar de klassieke indeling: <b>Meer → Indeling: Klassiek</b>.</li><li>De keuze geldt per toestel. De handleiding in de app volgt je keuze.</li></ol></div><div class=\"tut\"><h3>De zes knoppen onderin</h3><ol class=\"steps\"><li><b>Vandaag</b>: je startpad (tot alles af is), het doel van deze week, vier tegels en daaronder wat er vandaag voor je klaarstaat. Tik op <b>?</b> bij een tegel voor de uitleg waar het getal vandaan komt.</li><li><b>Groei</b>: het hoofdstuk Mijn groei &amp; ontwikkeling, met je leerlijn en de hele opleiding.</li><li><b>+</b> (midden): <i>Wat wil je vastleggen?</i> Een DTF-feit, een nabespreking of feedback aan een medecadet.</li><li><b>Werkboek</b>: je rode draad, de vaste basis (<a class=\"ho-go\" data-step=\"0\">hoofdstuk 0</a> tot en met 10) in vijf stappen: <i>Jezelf leren kennen</i>, <i>Leervraag</i>, <i>Doen en vastleggen</i>, <i>Reflecteren</i> en <i>Feedback en beoordeling</i>, met de status <i>klaar</i>, <i>bezig</i> of <i>open</i>. Wat je in de gereedschapskist aanzet (roos, nabespreking) staat met ⚒ bij stap 3. Bovenaan zoek je op een hoofdstuk. Verdieping (11 tot 13) en naslag (14 tot 17) staan onder <b>Meer hoofdstukken</b>. Met <b>Werkboek</b> bovenin een hoofdstuk ga je terug naar de lijst.</li><li><b>Postvak</b>: feedback van medecadetten en je teamleider, vragen om feedback en wat je zelf gaf. Een rood bolletje betekent dat er iets op je wacht.</li><li><b>Meer</b>: hetzelfde menu als ⋮ in de klassieke indeling: delen, back-up, onderzoek, handleiding en instellingen.</li></ol><div class=\"call tip\"><b>Tip</b> Overal in deze handleiding waar <a class=\"ho-go\" data-menu=\"…\"><i>⋮ → …</i></a> staat, gebruik je in de Dashboard-weergave <i>Meer → …</i>. De handleiding voor de Dashboard-weergave (aparte PDF) schrijft het al zo.</div></div><div class=\"tut\"><h3>Vandaag: je week en wat genoeg is (sinds 4.30)</h3><ol class=\"steps\"><li>Bovenaan Vandaag staat de datum met je opleidingsweek, bijvoorbeeld <i>week 10 van 35 · jouw 3e week</i> voor een doorstromer. Vul daarvoor je startdatum in bij je profiel.</li><li>Er staan hooguit drie dingen tegelijk; is het tijd voor een <b>meetmoment</b>, dan staat dat erbij.</li><li>Klap <b>Genoeg voor deze periode</b> open: de persoonlijkheidstest, een leervraag met als-dan-plan, zes DTF-feiten in vier weken en één reflectie. Meer mag, maar dit is genoeg om van te leren.</li></ol></div><div class=\"tut\"><h3>Oefenen met feedback ontvangen</h3><ol class=\"steps\"><li>Open <a class=\"ho-go\" data-menu=\"Oefenen met feedback ontvangen\"><b>⋮ → Oefenen met feedback ontvangen</b></a>. Je krijgt drie korte casussen, bijvoorbeeld: <i>Je groepscommandant zegt: \"Je briefing was te lang.\"</i></li><li>Kies wat je eerst doet. Je ziet meteen waarom dat wel of niet werkt: eerst begrijpen, dan pas reageren, en daarna één volgende stap kiezen.</li><li>Stel je daarna een als-dan-plan bij na feedback, dan krijg je het insigne <b>Bijsteller</b>.</li></ol></div><div class=\"tut\"><h3>Hulp en opslag</h3><ol class=\"steps\"><li>Open <a class=\"ho-go\" data-menu=\"Hulp en opslag\"><b>⋮ → Hulp en opslag</b></a>. Je ziet hoeveel fouten de app bijhield en hoeveel van de opslag in gebruik is.</li><li>Ging er iets mis? Tik op <b>Stuur foutrapport mee</b>: dat opent <b>Probleem melden</b> met de laatste fouten erbij. Er gaan geen antwoorden of namen mee.</li><li>Is de opslag 80% of voller, dan waarschuwt de app. Maak dan een back-up en haal oude foto's of bijlagen weg.</li></ol></div><section class=\"sec\" id=\"A19\"><div class=\"kicker\">Deel A · Reflectieboekje · Naslag en overzicht</div><h2>Hoofdstuk 17 · Roos van Leary</h2><button type=\"button\" class=\"ho-open\" data-step=\"18\">Open dit hoofdstuk in de app &rarr;</button><p class=\"lead\">Welk gedrag laat je zien in een groep, en zien anderen dat ook zo? Je DTF-feiten en de feedback van anderen op de Roos van Leary, met uitleg.</p><div class=\"tut row\"><div class=\"txt\"><h3>Gedrag kiezen op de roos</h3><ol class=\"steps\"><li>Open bij een nieuw DTF-feit <b>Roos van Leary (optioneel)</b>. Tik op de plek die past bij het gedrag dat je liet zien: de binnenring is <i>een beetje</i>, de buitenring <i>duidelijk</i>. Nog eens tikken of <b>Wissen</b> haalt de keuze weg.</li><li>Bij een feit dat al in je logboek staat, tik je op <b>Roos</b> om de plek te kiezen of te wijzigen.</li><li>Geef je feedback aan een medecadet, dan kun je ook daar de plek op de roos kiezen. Je teamleider kan het bij een DTF-notitie doen.</li><li>In het DTF-logboek filter je bij <b>Meer filters</b> op een soort gedrag.</li></ol></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Kiezen bij een DTF-feit</figcaption></figure></div></div><div class=\"tut row\"><div class=\"txt\"><h3>Je roos bekijken</h3><ol class=\"steps\"><li>Open dit hoofdstuk (Naslag en overzicht). Vanaf vijf feiten met een plek op de roos zie je hoe je gedrag verdeeld is: goud is wat jij koos, de blauwe lijn is wat medecadetten en je teamleider kozen.</li><li>Het stipje is je gemiddelde plek. Daaronder zie je die ook als twee balkjes: onder of boven, tegen of samen.</li><li>Bij <b>Per soort gedrag</b> zie je per sector wat het betekent, welk gedrag het vaak bij anderen uitlokt en welke van je feiten erbij horen.</li><li>Bij <b>Naast je persoonlijkheidstest</b> staan je uitkomsten op extraversie en verdraagzaamheid. Leg ze naast de roos, maar trek geen conclusies uit één van beide.</li><li>Onderaan staat de uitleg: hoe de roos werkt en hoe je hem gebruikt in het gesprek met je teamleider.</li></ol><div class=\"call info\"><b>Goed om te weten</b> Geen enkel gedrag op de roos is goed of fout. Het gaat erom dat je ziet wat je doet, wat dat bij anderen oproept en of je bewust kunt kiezen.</div><div class=\"call privacy\"><b>Privacy</b> De plek op de roos staat bij je DTF-feiten. Deel je het DTF-logboek met je teamleider, dan ziet hij die ook.</div></div><div class=\"phones\"><figure class=\"phone\"><img src=\"data:image/webp;base64,\" loading=\"lazy\"/><figcaption>Jouw roos</figcaption></figure></div></div>", "steps": {"A2": 0, "A3": 1, "A4": 2, "A5": 3, "A6": 4, "A7": 7, "A8": 8, "A9": 9, "A10": 11, "A11": 5, "A12": 13, "A13": 10, "A14": 14, "A15": 17, "A16": 15, "A17": 12, "A18": 16, "A19": 18}};
